/**
 * The optimization report: one model, two renderings.
 *
 * Markdown and HTML are produced from the same structured object rather than by
 * converting one into the other. That matters more than it looks: a Markdown
 * report and an HTML view generated by different code paths drift, and the drift
 * shows up as a number that disagrees between the page and the file — with no way
 * to tell which one is right. Here they cannot disagree, because they read the
 * same fields.
 *
 * ## Shape
 *
 * The section list follows the hub's 优化包模板 and the worked example in
 * `01-system/data/products/B0GSFPTD2H/comprehensive-optimization-*.md`, in that
 * order: 概况 → 埋词策略 → 逐字段 → 属性 → A+ → Q&A → 自检 → 上传指引 → 风险.
 * A report that leads with the field-by-field diff and buries the coverage matrix
 * answers "what changed" while leaving "did we use the listing" unasked.
 *
 * ## Three sections exist only to keep it honest
 *
 *   - **这份报告不判定的事.** `LLM_ONLY_CHECKS` lists the checks the docs ask for
 *     that code cannot make. A report saying "0 violations" while silently
 *     omitting them implies a clean bill of health it did not earn.
 *   - **丢词.** A rewrite that drops a word we already rank for reads better and
 *     quietly costs a ranking weeks later. Named at the top, because review time
 *     is the only cheap moment to fix it.
 *   - **站点未核验声明.** When the site has no verified rule source, the report
 *     says so and names which numbers are therefore provisional. Silently applying
 *     US limits to a JP listing produces a confident report about a rule set
 *     nobody has checked.
 *
 * ## One trap, recorded because it bit twice
 *
 * A backtick typed anywhere in the static part of a template literal ends the
 * string. The HTML below is one big template literal, so there are no backticks
 * in its static text — and dynamic content goes through `esc()`, which is safe
 * inside `${}` because the value is substituted rather than parsed.
 */

import { REVIEW_ITEMS } from './review.js'
/* F13-09：交付边界。`manualFieldRows` / `manualStatusLabel` 也从这个模块来 ——
   手填字段的三态（库内有 / 库内为空 / 库内没有对应列）只有一处实现，报告第十一节
   与交付清单读的是同一份 `done`。这两个函数以前就住在本文件里，本批把它们搬到
   交付边界那一侧（它才是「哪些字段要人填」这个问题的属主）。 */
import { buildDelivery, manualFieldRows, manualStatusLabel } from './delivery.js'
/* 每个字段「改了之后预期改变什么」—— 与 rationale（为什么这样改）配对。
   报告以前只有前者，读者看完不知道发布之后该看什么数。 */
import { expectationFor, expectationLine } from './expectation.js'
import {
  BULLET_FIELDS, FIELDS, IMAGE_ALT_FIELDS, fieldRank, isAttributeField, isPublishable, labelForField, sectionOf,
  writebackSplit,
} from '../rules/listing-fields.js'
import { ATTRIBUTES, REQUIRED_ATTRIBUTE_TARGET, attributeCoverage } from '../rules/attributes.js'
import { GLOBAL_LIMITS, profileFor, provisionalNote } from '../rules/marketplaces.js'
import { lexiconFor } from '../rules/lexicon.js'
import { draftCoverage, measureDraft } from './budget.js'
/* F14-02 §28.2 / §28.4 的**判据**那一层：摘要四字段、字段级置信度与风险、实际发布值。
   它们住在 `standards.js` 而不是本文件，理由在那一份的文件头 —— 判据要能被逐条打中，
   而排版不行。本文件只把结论放进模型，两种渲染都只读模型。 */
import {
  appliesToField, assessField, buildActivation, buildProvenance, dataCutoffOf,
} from './standards.js'
/* F14-10：导出件的「数据新鲜度」判据（「非实时」必须能由内容推出来，见那份文件头）。
   它不接 store —— 只认已经读出来的证据包与算好的数据截止。 */
import { buildFreshness } from './freshness.js'
/* F14-10：Excel 是第三种渲染，与 Markdown / HTML 念**同一份模型**。写出器在
   `domain/sheets/` 里，零依赖（只用 `node:zlib`）—— 本仓装了就能用，不需要构建步骤。 */
import { writeXlsx } from '../sheets/xlsx-write.js'

const esc = (value) => String(value ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')

/** A Markdown table cell cannot contain a raw pipe or a newline. */
const cell = (value) => String(value ?? '').replace(/\|/g, '\\|').replace(/\r?\n/g, '<br>').trim()

/**
 * A code fence that cannot be closed by its own content.
 *
 * Drafts are prose and prose contains backticks; a fixed ``` fence around text
 * that already has one produces a block that ends early and a report that looks
 * truncated.
 */
function fence(text, lang = '') {
  const body = String(text ?? '')
  const longest = (body.match(/`+/g) ?? []).reduce((max, run) => Math.max(max, run.length), 0)
  const bar = '`'.repeat(Math.max(3, longest + 1))
  return `${bar}${lang}\n${body}\n${bar}`
}

const SEVERITY_LABEL = { block: '阻断', warn: '警告' }

/**
 * Display name for any field.
 *
 * Re-exported from the vocabulary rather than redefined: the tools and the page
 * need the same labels, and two label maps is how one field ends up named
 * differently in two places the reader is comparing side by side.
 */
export { labelForField }

const parseJson = (value, fallback) => {
  if (value === null || value === undefined || value === '') return fallback
  if (typeof value === 'object') return value
  try {
    return JSON.parse(value)
  } catch {
    return fallback
  }
}

/**
 * 报告的一级章节表 —— **目录、两种渲染的标题、HTML 锚点**都只从这一张表来。
 *
 * §28.4 要求报告详情有目录导航与证据跳转。目录一旦和第二份「章节标题清单」并存，
 * 加一节就会变成「正文里有、目录里没有」，而那种不一致没有任何东西会报错。
 * 所以标题只写在这里：Markdown 走 `## ${sectionTitle(id)}`，HTML 走
 * `<h2 id="${id}">`，目录走 `REPORT_SECTIONS` 本身。三处同源，加一节只有一处要改。
 *
 * `optional` 的那几节由内容决定出不出（没有可粘贴字段就没有第六节）。**判断在
 * `visibleSections` 一处**，两种渲染问它，而不是各自再算一遍。
 */
export const REPORT_SECTIONS = [
  /* F14-10：导出件的头信息排在最前 —— 报告 ID / 对象 / 范围 / 来源 / 质量告警 /
     数据新鲜度。它必须排在目录之后的第一节，理由与「优化模式优先于数据」相同：
     读者跳读时先看到「这是什么、哪一刻的」，再看到数字。 */
  { id: 's-export', title: '导出件头信息' },
  { id: 's-provenance', title: '报告头信息' },
  { id: 's1', title: '一、结论' },
  { id: 's2', title: '二、产品概况' },
  { id: 's3', title: '三、埋词策略' },
  { id: 's4', title: '四、逐字段优化' },
  { id: 's5', title: '五、属性字段' },
  { id: 's6', title: '六、可直接复制粘贴的内容', optional: 'pasteable' },
  { id: 's7', title: '七、独立编辑器里的字段', optional: 'surfaceRows' },
  { id: 's8', title: '八、合规校验' },
  { id: 's9', title: '九、字符与字节预算' },
  { id: 's10', title: '十、事实台账', optional: 'factLedger' },
  { id: 's11', title: '十一、必须人工填的字段' },
  { id: 's12', title: '十二、上架操作清单' },
  { id: 's13', title: '十三、自检总表' },
  { id: 's-evidence', title: '附录、证据包（本轮冻结的十一类）', optional: 'evidencePack' },
]

const sectionTitle = (id) => REPORT_SECTIONS.find(section => section.id === id)?.title ?? id

/** The table of contents' own title — one string, two renderings. */
const TOC_TITLE = '目录'

/** Which of the optional sections this model actually has. One judgement, two renderings. */
function visibleSections(model) {
  return REPORT_SECTIONS.filter((section) => {
    if (section.optional === 'pasteable') return (model.pasteable ?? []).length > 0
    if (section.optional === 'surfaceRows') return (model.surfaceRows ?? []).length > 0
    if (section.optional === 'factLedger') return model.hasFactLedger === true
    if (section.optional === 'evidencePack') return model.evidencePack !== null
    return true
  })
}

/** 证据包三类状态的中文说法 —— 与 `evidence.js` 的三态一一对应，不合并。 */
const EVIDENCE_STATUS_LABELS = { frozen: '冻结', absent: '不存在', not_modelled: '未建模' }

const evidenceStatusLabel = (status) => EVIDENCE_STATUS_LABELS[status] ?? status

/** A value short enough to sit in a table cell without becoming the table. */
const brief = (value, max = 60) => {
  const text = String(value ?? '')
  if (text === '') return '（空）'
  return text.length <= max ? text : `${text.slice(0, max)}…`
}

/**
 * Which frozen evidence classes bear on one field. §28.4 的「证据跳转」落到实处就是这一句：
 * 一个字段的结论**依据哪几类证据**，得从字段本身推出来，不能靠人在十一类里翻。
 *
 * 依据是证据包自己的 `appliesTo`（`all` / `copy` / `keywords` / `field`），不是第二张表。
 */
function evidenceForField(model, field) {
  if (model.evidencePack === null) return []
  const section = isAttributeField(field) ? 'attributes' : (sectionOf(field) ?? '')
  const shapes = ['all']
  if (section === 'title' || section === 'bullets' || section === 'description') shapes.push('copy')
  else if (section === 'search_terms') shapes.push('keywords')
  else if (section === 'attributes') shapes.push('field')
  return model.evidencePack.rows.filter(row => shapes.includes(row.appliesTo))
}

/**
 * 合规结论里那个字段名的**跳转**（§28.4 的证据跳转里「从结论回到那一格」这一半）。
 *
 * 伪字段（`bullets` / `draft`）没有自己的锚点 —— 给它们编一个 `#field-bullets` 会
 * 变成死链接，而一个点了没反应的链接比没有链接更坏。所以只有真的在逐字段里出现过的
 * 字段才链。
 */
function fieldAnchorLink(model, field, label) {
  const known = model.rows.some(row => row.field === field)
  return known ? `<a href="#field-${esc(field)}">${esc(label)}</a>` : esc(label)
}

/**
 * The product facts shown at the top, in one place so the two renderings cannot
 * disagree.
 *
 * The column names are this plugin's (`bsr`, `category`, `reviews`), not the
 * hub's Python model names (`bsr_rank`, `bsr_category`, `review_count`). Reading
 * the hub's names here produced a product section of empty cells that looked like
 * a collection gap rather than a field-name mismatch — a section that is silently
 * blank is worse than one that is missing, because nothing points at it.
 */
function productRows(asin) {
  if (asin === null || asin === undefined) return null
  return [
    ['ASIN', asin.asin],
    ['站点', asin.marketplace],
    ['品牌', asin.brand ?? '—'],
    ['价格', `${asin.price ?? '—'} ${asin.currency ?? ''}`.trim()],
    ['BSR', `${asin.bsr ?? '—'} ${asin.category ?? ''}`.trim()],
    /* 评论数的兜底原来是 0：没采集就印「0 条」——而同一行的 rating 用的是「—」，
       证明 null 在这里是合法状态。两个格必须说同一种话：没取到就印「—」。 */
    ['评分', `${asin.rating ?? '—'}（${asin.reviews ?? '—'} 条）`],
  ]
}

/**
 * How the 「优化前」 column's source is described, keyed by `listing.origin`.
 *
 * `draft-applied` is the one that matters: the listing row was written by this
 * plugin's own write-back, so "优化前" is the plugin's previous draft, **not** the
 * copy that is live on the storefront. Reporting that as a plain "优化前" is how a
 * report ends up comparing the new draft against its own shadow while sounding
 * like it compared against the real listing. `danger` marks the sources that
 * need the reader's attention, and drives the bold/red rendering.
 */
const BEFORE_ORIGIN = {
  'draft-applied': { phrase: '本插件上一版草稿 —— 不是线上真实文案', danger: true },
  snapshot: { phrase: '采集快照', danger: false },
  manual: { phrase: '人工录入', danger: false },
}

/** The label for the run's 「优化前」 listing, or null when there is no listing. */
function beforeSourceLabel(listing) {
  if (listing === null || listing === undefined) return null
  const entry = BEFORE_ORIGIN[listing.origin] ?? {
    phrase: '未知 —— v8 之前写入，无法判断是线上文案还是插件草稿',
    danger: true,
  }
  return { origin: listing.origin ?? null, phrase: entry.phrase, danger: entry.danger }
}

/** The Markdown 「优化前」 label, carrying the source when the model has one. */
function beforeLabelMarkdown(source) {
  if (source === null) return '**优化前**'
  return source.danger ? `优化前（来源：**${source.phrase}**）` : `优化前（来源：${source.phrase}）`
}

/** The HTML 「优化前」 label — same wording, the danger source emphasised. */
function beforeLabelHtml(source) {
  if (source === null) return '优化前'
  return `优化前（来源：${source.danger ? `<strong class="bad">${esc(source.phrase)}</strong>` : esc(source.phrase)}）`
}

/**
 * 导出件的头信息 —— 报告 ID / 对象 / 范围 / 来源 / 质量告警 / 数据新鲜度。
 *
 * ## 为什么这六行必须在**模型**里，不在渲染里
 *
 * 审计 F14-10 的原话是「导出件头部缺 报告 ID/对象/范围/来源/质量告警」。这五件事
 * 每一件都能从库里算出来，所以每一件都必须是模型的一个字段，而不是 Markdown 里
 * 拼的一段话 —— 否则同一份报告的 HTML 与 Excel 会各拼一遍，而它们漂开时没有任何
 * 东西会报错。
 *
 * ## 每一行的「值」都带出处
 *
 * 第三列（`note`）不是说明文，是**这一格怎么算出来的**：哪个表、哪一列、哪个计数。
 * 有了它，读的人不必相信这句话，他可以自己去库里对。这也是测试的读法 ——
 * `tests/f14-10-report-export.mjs` 把每个值重新从库里算一遍再比。
 *
 * ## 六行而不是五行
 *
 * 第六行「数据新鲜度」是审计第 3 条（「必须声明它不是实时数据」）的落点。它不是
 * 一句「非实时」：`freshness.statement` 由生成时刻、数据截止、两者差值、证据包逐类
 * 状态与指标口径限制拼出来（见 `freshness.js` 的文件头），所以「非实时」这三个字
 * **能由内容推出来**，而不是贴上去的标签。
 */
function buildExportHeader(model) {
  const run = model.run ?? {}
  const runId = String(run.id ?? '').trim()
  const asinText = String(model.asin?.asin ?? run.asin ?? '').trim().toUpperCase()
  const marketText = String(model.asin?.marketplace ?? run.marketplace ?? model.marketplace?.code ?? '').trim().toUpperCase()
  const rows = []

  /* ── ① 报告 ID ─────────────────────────────────────────────────────────── */
  rows.push({
    id: 'report-id',
    label: '报告 ID',
    value: runId === '' ? '（这一轮没有 id）' : runId,
    /* 三个地址指同一份字节，所以「报告 ID」只有一个 —— 如果哪天页面、文件与库各说
       各的 id，这一行会立刻读起来不对。 */
    note: '这一份文件的身份 = `optimization_run.id`，也是报告库里这一条（kind=optimization）的 `ref_id`。'
      + '`/report/<id>` 打开的是同一份内容，不是第二份副本。',
  })

  /* ── ② 对象 ─────────────────────────────────────────────────────────────── */
  const objectParts = []
  objectParts.push(asinText === '' ? 'ASIN 未记录' : asinText)
  objectParts.push(marketText === '' ? '站点未记录' : `${marketText}（${model.marketplace?.label ?? marketText}）`)
  rows.push({
    id: 'report-object',
    label: '对象',
    value: objectParts.join(' · '),
    note: `ASIN 与站点取自 \`optimization_run.asin\` / \`.marketplace\``
      + (model.asin === null || model.asin === undefined
        ? '；`asin` 表里这一行读不到（所以产品概况一节是空的，那是「没有这一行」，不是「字段都是 0」）。'
        : `，并与 \`asin\` 表那一行核对过（品牌 ${model.asin.brand ?? '—'}）。`),
  })

  /* ── ③ 范围 ─────────────────────────────────────────────────────────────── */
  /* 埋词位置走 `planPositionText`：没有计划时它说「未记录」，不在这里另算一个 0
     —— 同一份报告里「范围」这一行的 0 与页脚的「0 个」是同一句话，两处各算一遍
     就会出现一行说 0、一行说未记录。 */
  const scopeParts = [
    `字段 ${model.rows.length} 个（采纳 ${model.accepted.length} / 拒绝 ${model.rejected.length} / 待定 ${model.pending.length}）`,
    `埋词位置 ${planPositionText(model)}`,
    `证据 ${model.freshness.counts.evidenceKinds} 类`,
    `预算对照 ${model.budgets.length} 个字段`,
  ]
  rows.push({
    id: 'report-scope',
    label: '范围',
    value: scopeParts.join(' · '),
    note: '字段数 = `optimization_run` 下这一轮的草案行数；埋词位置 = 本轮全局计划的 `positions`；'
      + '证据类数 = 本轮冻结的证据包条数；预算对照 = 计入字符/字节上限的字段数。'
      + '四者都是**这一轮**的范围，不是全库。',
  })

  /* ── ④ 来源 ─────────────────────────────────────────────────────────────── */
  const sources = []
  for (const row of model.freshness.evidence.rows) {
    if (row.status !== 'frozen') continue
    const text = String(row.source ?? '').trim()
    if (text !== '' && !sources.includes(text)) sources.push(text)
  }
  rows.push({
    id: 'report-source',
    label: '来源',
    value: model.freshness.evidence.rows.length === 0
      ? '这一轮没有冻结证据包：数字来自 optimization_run 的草案行与本轮规则快照'
      : `${sources.length} 个来源：${sources.join('；')}`,
    note: model.freshness.evidence.rows.length === 0
      ? '**这里不是「本仓没有来源」**：证据包的十一类都建了（`domain/optimize/evidence.js`），'
        + '缺的是这一轮建轮次时没有冻结那一份。重跑一次收尾会补冻。'
      : '逐条来自证据包每一类的 `source`（冻结时记下的表 + 取数口径），不是现在重新推导的。',
  })

  /* ── ⑤ 质量告警 ─────────────────────────────────────────────────────────── */
  const skipped = Array.isArray(model.validation?.skipped) ? model.validation.skipped.length : 0
  const warnParts = [
    `${model.counts.block} 条阻断 / ${model.counts.warn} 条警告`,
    `未执行规则 ${skipped} 条`,
    `站点规则${model.provisional === null ? '已核验' : '**未核验**'}`,
    `词法${model.lexicon?.tier === 'authored' ? '已核验' : '**近似**'}`,
  ]
  if (model.applyListing?.ok === false) warnParts.push('**写回失败**')
  const missingEvidence = model.freshness.counts.evidenceAbsent + model.freshness.counts.evidenceNotModelled
  warnParts.push(`证据缺 ${missingEvidence} 类`)
  rows.push({
    id: 'report-quality',
    label: '质量告警',
    value: warnParts.join(' · '),
    note: '阻断/警告 = 本轮校验的计数（`validation.counts`，与第八章同一份）；未执行规则 = 本站点跳过执行的规则条数；'
      + '站点规则与词法各自三态（已核验 / 未核验 / 近似）；写回只在真失败时出现；'
      + '证据缺 = 证据包里 `absent` 与 `not_modelled` 的类数。**「0 条阻断」是一次测量，「读不到规则集」不是 0。**',
  })

  /* ── ⑥ 数据新鲜度（审计第 3 条的落点）────────────────────────────────────── */
  rows.push({
    id: 'data-freshness',
    label: '数据新鲜度',
    value: model.freshness.headline,
    note: model.freshness.statement,
  })

  return { rows, realtime: false, label: model.freshness.label }
}

/**
 * Build the report model from whatever the run actually has.
 *
 * Everything is optional. A report assembled from a partial run must still render
 * and must say what is missing, rather than presenting an absent section as an
 * empty one — "0 warnings" and "we could not check" are different claims.
 */
export function buildReportModel({
  run = {},
  asin = null,
  listing = null,
  drafts = [],
  coverage = null,
  plan = null,
  gates = null,
  validation = null,
  rules = {},
  /* R-91（需求方指定）：当前生效的**字段模板**整份传进来 —— 报告要按它印全量字段。
     注意它在本函数的**第一层**参数里（不是 `options.templateItems`）：
     2026-10-26 我第一次写成 `options.templateItems`，结果模型里 `templateMissing` 恒为 0，
     报告只印了 9 行 —— 一个「参数放错层」的错，症状是「功能看起来没生效」。 */
  templateItems = [],
  options = {},
  /* The outcome of the write-back, when one was attempted. `null` means the
     caller did not try (the default: applyListing off). The report must never
     claim a write that did not happen, so the "已写入" line is driven by this
     value and nothing else — see `writeback` below. */
  applyListing = null,
  /* F13-09：这一轮的发布登记（模块 14 §6）。`[]` 表示「一条都没有」—— 交付边界的
     「已登记」那一列由它重算，而不是由任何自报的状态得出。 */
  publications = [],
  /* F14-02 §28.2：这一轮**冻结的证据包**（`readEvidence` 的整份返回，或 `null`）。
     「数据截止」只从它算，不去读今天的活数据 —— 理由在 `standards.js` 的
     `dataCutoffOf` 文件头：报告要能在三个月后仍然解释得通。
     `null` = 这一轮还没有证据包（**不是**「证据是空的」）。 */
  evidence = null,
  /* F14-02 §28.2：这一轮关联的 Agent 运行（`store/agent.js` 的 `getRun` 结果，或 `null`）。
     `null` 有两种含义，报告必须分开说：没有 `agent_run_id`（没关联），以及
     有关联但那一行已经查不到（`run.agent_run_id` 非空而这里是 null）。 */
  agentRun = null,
} = {}) {
  const ordered = [...drafts].sort((a, b) => {
    const bySection = fieldRank(a.field) - fieldRank(b.field)
    if (bySection !== 0) return bySection
    return (a.id ?? 0) - (b.id ?? 0)
  })
  const accepted = ordered.filter(draft => draft.accepted === 1)
  const rejected = ordered.filter(draft => draft.accepted === 0)
  const pending = ordered.filter(draft => draft.accepted === null || draft.accepted === undefined)

  /* The headline counts come from the same computation the gates use, not from
     summing the stored per-field rows. The two are not the same quantity: a
     document-level rule reports on the pseudo-field `draft`, and persistence
     writes one row per real field, so the sum silently dropped those — the
     report said 23 warnings in one line and 19 in the next, and neither number
     was wrong on its own terms. One number, one source. */
  const counts = validation?.counts ? { ...validation.counts } : { block: 0, warn: 0 }
  if (validation === null || validation === undefined) {
    for (const draft of ordered) {
      for (const violation of parseJson(draft.violations_json, [])) {
        counts[violation.severity] = (counts[violation.severity] ?? 0) + 1
      }
    }
  }

  const afterFields = {}
  for (const draft of ordered) {
    const value = draft.after ?? draft.before
    if (value === null || value === undefined || value === '') continue
    afterFields[draft.field] = value
  }

  const marketplace = String(asin?.marketplace ?? options.marketplace ?? 'US')
  const profile = profileFor(marketplace)

  const rows = ordered.map(draft => {
    const violations = parseJson(draft.violations_json, [])
    const section = sectionOf(draft.field) ?? 'unknown'
    return {
      field: draft.field,
      label: labelForField(draft.field),
      section,
      before: draft.before ?? null,
      after: draft.after ?? null,
      accepted: draft.accepted === 1,
      rationale: draft.rationale ?? null,
      /* 「为什么这样改」与「改完该看什么数」是两件事：只有前者，读者发布之后
         没有任何东西能判断这次改动成不成功。 */
      expected: expectationFor(draft.field, section),
      keywords: parseJson(draft.keywords_json, []),
      violations,
      block: violations.filter(violation => violation.severity === 'block').length,
      warn: violations.filter(violation => violation.severity === 'warn').length,
      publishable: isPublishable(draft.field),
      needsConfirmation: isAttributeField(draft.field) || FIELDS[draft.field]?.modelControlled === false,
    }
  })

  const groups = []
  /* 2026-10-26（R-91，需求方指定）：报告的字段是**全量**的 —— 由调用方把当前生效的字段模板
     （`options.templateItems`）整份交进来，本轮没有草稿的字段不进 `rows`（它们没有 before/after），
     而是进 `templateMissing`，由渲染器在对照表末尾逐行印出来（写「本轮没有草稿」）。
     **不从表里消失**是重点：一张只说「我写了 9 行」的表，读者无法知道模板本来要求 66 行。 */
  const draftedIds = new Set(rows.map(row => row.field))
  const templateMissing = templateItems
    .filter(item => item !== null && item !== undefined && !draftedIds.has(item.id))
    .map(item => ({
      id: item.id,
      label: item.label ?? item.id,
      kind: item.kind ?? 'copy',
      section: item.section ?? null,
      required: item.required === true,
      limit: item.limit ?? null,
    }))

  for (const row of rows) {
    const existing = groups.find(group => group.id === row.section)
    if (existing) existing.rows.push(row)
    /* `fieldRank` is the one source of section order — the same function the
       tools and the budgets use. A second inline order table here is how a new
       section ends up in one place but not the other. */
    else groups.push({ id: row.section, label: sectionLabel(row.section), order: fieldRank(row.field), rows: [row] })
  }
  groups.sort((a, b) => a.order - b.order)

  const budgets = measureDraft(afterFields, { marketplace, category: asin?.category ?? options.category })

  /* ── F14-02：字段级与实际发布值，都在**建模型时算一次** ────────────────────────
     两种渲染都只读这里的结果。逐字段的置信度/风险不是排版选择，是判据（规则表在
     `standards.js`）；把它写进任一渲染里，另一侧就会给出另一个答案。 */
  const activation = buildActivation({ publications, rows })
  const budgetOfField = new Map(budgets.map(entry => [entry.field, entry]))
  const skippedRules = Array.isArray(validation?.skipped) ? validation.skipped : []
  for (const row of rows) {
    const published = activation.byField[row.field] ?? null
    const rules = skippedRules.filter(entry => appliesToField(entry.field, row.field)).map(entry => entry.ruleId)
    const assessment = assessField({
      before: row.before,
      after: row.after,
      block: row.block,
      warn: row.warn,
      needsConfirmation: row.needsConfirmation,
      publishable: row.publishable,
      budget: budgetOfField.get(row.field) ?? null,
      skippedRules: rules,
      published: published === null ? null : { value: published.value },
    })
    /* 就地补到行上：`groups` 里放的是**同一批对象**，所以分组渲染读到的也是这一份 ——
       再复制一遍就会有两份字段结论。 */
    row.published = published
    row.skippedRules = rules
    row.confidence = assessment.confidence
    row.risk = assessment.risk
  }

  /* 摘要四字段（§28.2）。`provenance.rows` 是**值的唯一措辞处**：两种渲染都念它，
     所以 Markdown 与 HTML 不可能对同一个字段说出两句话。 */
  const packageJson = parseJson(run.package_json, null)
  /* 数据截止**只算一次**：`buildProvenance` 与 `buildFreshness` 读的是同一份
     `dataCutoffOf` 结果。各算一次在本仓的历史里就是「同一件事两处调用 → 两处不同
     逻辑」的第一步，而这里两处恰好都会印给读者看。 */
  const cutoff = dataCutoffOf({ evidence })
  const provenance = buildProvenance({
    run,
    packageJson,
    agentRun,
    drafts: ordered,
    cutoff,
  })
  /* F14-10：这一份导出件代表哪一刻的什么。判据在 `freshness.js`（它连 store 都不接，
     只认已经读出来的行），这里只把读到的证据包与算好的截止时间交过去。 */
  const freshness = buildFreshness({ run, evidence, cutoff })
  const evidencePack = evidence !== null && evidence !== undefined && evidence.ok === true
    ? {
      rows: provenance.cutoff.rows,
      counts: evidence.counts ?? null,
      missing: Array.isArray(evidence.missing) ? evidence.missing : [],
      frozenAt: evidence.frozenAt ?? null,
      lateFreeze: evidence.lateFreeze === true,
    }
    : null

  /* The write-back split is a property of the field registry, not of whether a
     write ran, so it is always computed. The counts and the group names both
     come from `writebackSplit`, so a report cannot print a number the registry
     does not imply. */
  const writeback = writebackSplit(rows.map(row => row.field))

  /* The keyword lexicon is a *separate* disclosure from `provisional` above. That
     one is about unverified **site rules** (limits, units); this one is about an
     approximated **keyword lexicon** (which words count as questions/specs/scenes,
     and whether the word-repeat rule applies). A site can have both (DE), one
     (JP), or neither (US) — collapsing them would let "the site's rules are
     unverified" stand in for "the support positions were counted with the wrong
     word list", which are different things the reader has to act on differently. */
  const lexicon = lexiconFor(marketplace)

  /* 交付边界（F13-09）。**在这里算一次、在载荷里带出去**，因为两个地方要它：
     报告正文（操作清单 + 交付边界那三行数字）与工作台面板（发布登记跳转）。
     两边各调一次 `buildDelivery` 会得到同一个答案 —— 但那就成了两处调用，
     而「同一件事两处调用」在本仓的历史里迟早会变成两处**不同的**逻辑。
     所以：报告模型里放一份，页面从 `data.optimizations.delivery` 读那一份。
     `publications` 是这一轮的发布登记（模块 14 §6）—— 操作清单的「已登记」由它重算，
     没有传就是「这一轮读不到登记」，而不是「登记里一个字段都没有」。 */
  const manualRows = manualFieldRows(asin)
  const delivery = buildDelivery({
    run: {
      id: run.id ?? null,
      asin: asin?.asin ?? run.asin ?? null,
      marketplace,
      draftVersion: run.draft_version ?? run.draftVersion ?? null,
    },
    rows: rows.map(row => ({ field: row.field, accepted: row.accepted, after: row.after })),
    manualFields: manualRows,
    publications,
  })

  const model = {
    run,
    asin,
    listing,
    marketplace: profile,
    provisional: provisionalNote(marketplace),
    /* `note` is the support-position caveat; `repeatNote` is the *separate*
       disclosure that the title word-repeat rule does not apply on a non-Latin
       site. Both are carried so the report's ⚠️ block can cover the title rule
       and not only the support positions. */
    lexicon: {
      code: lexicon.code,
      tier: lexicon.tier,
      authored: lexicon.authored,
      script: lexicon.script,
      note: lexicon.note,
      repeatNote: lexicon.repeatNote,
      repeatApplicable: lexicon.repeatApplicable,
    },
    writeback,
    applyListing,
    /* Where the 「优化前」 column actually came from. Null when the report has no
       listing to compare against. */
    beforeSource: beforeSourceLabel(listing),
    drafts: ordered,
    accepted,
    rejected,
    pending,
    counts,
    afterFields,
    groups,
    rows,
    /* R-91：模板里有、本轮没草稿的字段 —— 渲染器要逐行印它们（「本轮没有草稿」）。 */
    templateMissing,
    budgets,
    coverage,
    plan,
    gates,
    validation,
    rules,
    attributes: attributeCoverage(afterFields),
    attributeRows: REQUIRED_ATTRIBUTE_IDS.map(id => ({
      id,
      label: ATTRIBUTES[id]?.label ?? id,
      value: afterFields[`attribute.${id}`] ?? null,
      specific: ATTRIBUTES[id]?.specific === true,
      note: ATTRIBUTES[id]?.note ?? null,
    })),
    /* `done` used to be hard-coded `false`, so section eleven listed all seven
       fields as "to fill" whether or not the store already held the value. It is
       now derived: `true` when the store has the counterpart value, `false` when
       the field is derivable but empty, and `null` when the store has no column
       that can answer the question — a tri-state, never a constant.
       F13-09: the same array is handed to `buildDelivery`, so the checklist and
       section eleven cannot disagree about whether a hand-fill field is known. */
    manualFields: manualRows,
    draftCoverage: draftCoverage(afterFields),
    /* F13-08：报告 8.3 列的是**审阅清单**（14 项），不是 `LLM_ONLY_CHECKS` 的 11 项 ——
       同一份清单在报告与工作台面板上必须是同一份，否则「面板上第 12 项」在报告里
       根本不存在。11 项是它的一部分（`review.js` 从上游 map 出来，不抄）。 */
    llmOnly: REVIEW_ITEMS,
    /* F13-09：交付边界（可复制字段 / 操作清单 / 发布登记跳转 / 三种「没有」）。 */
    delivery,
    dropped: coverage?.lost ?? [],
    gained: coverage?.gained ?? [],
    productRows: productRows(asin),
    options,
    /* ── F14-02 §28.2 ──────────────────────────────────────────────────────────
       摘要四字段、字段级置信度与风险、实际发布值。它们都在模型里，不在渲染里 ——
       所以「改坏 buildReportModel ⇒ Markdown 与 HTML 两侧同时变红」是一条结构上的
       事实，不是一条纪律。 */
    provenance,
    /* F14-10：数据新鲜度（「非实时」由内容推出）与导出件头信息。两者都在模型里，
       所以三种渲染（Markdown / HTML / Excel）念的是同一份 —— 改坏这里，三条断言
       一起红，那不是纪律，是结构。 */
    freshness,
    activation,
    evidencePack,
    /* 两节内容的存在性判断收进模型：以前 `pasteable` / `surfaceRows` 在 Markdown 与
       HTML 里**各算一遍**，两份过滤器迟早会有一份漏掉一个条件，然后同一轮报告在文件里
       有第六节、在页面上没有。现在一处算、两处读。 */
    pasteable: rows.filter(row => row.publishable && row.after !== null && row.accepted),
    surfaceRows: rows.filter(row => !row.publishable && row.after !== null),
    hasFactLedger: plan?.factLedger !== null && plan?.factLedger !== undefined,
  }
  /* 目录/章节判断要读模型本身（哪些可选节真的有内容），所以放在对象建好之后。 */
  model.sections = visibleSections(model)
  /* 导出件头信息读的是整份模型（范围要数草案行、来源要念证据包、质量告警要读校验计数），
     所以放在模型建完、章节表之前 —— 它自己不影响章节存在性。 */
  model.exportHeader = buildExportHeader(model)
  return model
}

/* Section ordering used to be a second, inline `{title:10, …}` table here.
   That duplicated `listing-fields.js:SECTIONS[].order`, and the two could drift
   the moment a section was added. `fieldRank` is the one authority now. */

const SECTION_LABEL = {
  title: '标题', bullets: '五点描述', description: '产品描述', search_terms: '后台搜索词',
  item_highlights: '产品亮点', attributes: '属性字段', aplus: 'A+ 内容', brand_story: '品牌故事',
  qa: 'Q&A 问答', images: '图片 Alt Text', video: '视频脚本',
}

const sectionLabel = (id) => SECTION_LABEL[id] ?? id

/** Kept as a module-level import shim so the attribute rows cannot fall out of sync. */
const REQUIRED_ATTRIBUTE_IDS = Object.keys(ATTRIBUTES).filter(id => ATTRIBUTES[id].required)

/* ── Markdown ──────────────────────────────────────────────────────────────── */

/**
 * 2026-10-26（R-89）：对照表的一个格子。
 *
 * 三件事必须在这一处做完，否则表格会被正文撑破：
 * - **换行**变 `<br>` —— 五点/描述的正文是多行的，原样放进表格会把这一行截断；
 * - **竖线**转义 —— 正文明天出现一个 `|`，表格就多出一列；
 * - **空值**写「（空）」而不是留空白 —— 空白读起来像「这里没内容」，而事实是
 *   「这个字段这一轮没有原值/没有说明」，那是两句话。
 */
function mdCell(value) {
  if (value === null || value === undefined || String(value).trim() === '') return '（空）'
  return String(value).replace(/\|/g, '\\|').replace(/\r?\n/g, '<br>')
}

/** HTML 侧同一件事的纯文本版（转义由调用处的 `esc` 负责）。 */
function cellText(value) {
  if (value === null || value === undefined || String(value).trim() === '') return '（空）'
  return String(value)
}

export function renderMarkdown(model) {
  const lines = []
  const push = (...values) => lines.push(...values)

  push(`# Listing 优化报告 — ${model.asin?.asin ?? model.run?.asin ?? '（未指定 ASIN）'}`)
  push('')
  push(`> 站点：${model.marketplace.label}（${model.marketplace.code}）｜优化轮次：#${model.run?.id ?? '—'}｜状态：${statusLabel(model.run?.status)}`)
  push(`> 规则集：${model.rules?.version ?? '—'}｜埋词位置：${planPositionText(model)}｜字段：${model.rows.length} 个`)
  if (model.run?.rules_json !== undefined && model.run?.rules_json !== null) {
    push('> 本轮判定用的是**本轮快照的规则**，不是今天的规则 —— 所以几个月后这份报告仍然解释得通。')
  }
  push('')

  /* 目录（§28.4）。条目来自 `model.sections` —— 与正文标题、HTML 锚点是同一张表，
     所以不会出现「正文有、目录没有」。 */
  push(`## ${TOC_TITLE}`)
  push('')
  for (const section of model.sections) push(`- [${section.title}](#${section.id})`)
  push('')

  /* ── F14-10 导出件头信息 ─────────────────────────────────────────────────────
     六行，第三列是「这一格是怎么来的」。**标签与值分列**是这里能被断言的前提：
     `| 数据新鲜度 | <值> | <出处> |` 三格分开，测试切出第二格再读；把标签与值写进
     一句话，改坏了值标签还在，`includes` 照样绿（本仓 includes 审计 round 2 抓过的
     形状）。 */
  push(`## ${sectionTitle('s-export')}`)
  push('')
  push('| 字段 | 值 | 这一格是怎么来的 |')
  push('| --- | --- | --- |')
  for (const row of model.exportHeader.rows) {
    push(`| ${cell(row.label)} | ${cell(row.value)} | ${cell(row.note ?? '')} |`)
  }
  push('')
  /* 「非实时」单独抬出来一块：表格里的那一行容易被略过，而这一份文件最容易被误读的
     就是「数是真的、就是今天的」。句子与表格那一格是**同一份**（`freshness`），
     不是第二段措辞。 */
  push(`> ⚠️ **${model.freshness.label}**：${model.freshness.statement}`)
  push('')

  /* 摘要四字段（§28.2）。**标签与值分列**：`| 数据截止 | 2026-… |`。
     两列分开才能被逐格断言 —— 把标签和值写在一句话里，改坏了值标签还在，
     `includes('数据截止')` 照样绿（本仓 includes 审计 round 2 抓过的形状）。 */
  push(`## ${sectionTitle('s-provenance')}`)
  push('')
  push('| 字段 | 值 | 这一格是怎么来的 |')
  push('| --- | --- | --- |')
  for (const row of model.provenance.rows) {
    push(`| ${cell(row.label)} | ${cell(row.value)} | ${cell(row.note ?? '')} |`)
  }
  push('')

  if (model.provisional !== null) {
    push('## ⚠️ 站点规则未核验')
    push('')
    push(model.provisional.text)
    push('')
  }

  /* A second, separate disclosure: the support-position rules were matched with
     this site's keyword lexicon, and when that lexicon is an approximation the
     report says so. Without it a non-English listing gets a thinner plan and no
     explanation — the failure the whole lexicon change exists to remove. The
     title word-repeat rule is disclosed here too: on a non-Latin site it does not
     apply at all, and that must not read as a pass. */
  if (model.lexicon?.note || model.lexicon?.repeatNote) {
    push('## ⚠️ 关键词词法未核验')
    push('')
    if (model.lexicon.note) push(model.lexicon.note)
    if (model.lexicon.repeatNote) push(model.lexicon.repeatNote)
    push('')
  }

  /* 一、结论 */
  push(`## ${sectionTitle('s1')}`)
  push('')
  push(`- 采纳 **${model.accepted.length}** 个字段，未采纳 ${model.rejected.length} 个，待定 ${model.pending.length} 个`)
  push(`- 阻断 **${model.counts.block}** 项，警告 **${model.counts.warn}** 项${model.counts.block === 0 ? '（无阻断项，可以上架）' : '（阻断项必须先处理）'}`)
  push(`- 属性填写 **${model.attributes.filledCount}/${model.attributes.target}**`)
  if (model.plan?.coverageMatrix) {
    const summary = model.plan.coverageMatrix.summary
    /* 同一个值走同一个入口（`planFillRate`）：读不到就说「未记录」。
       这里以前直接 `Math.round(summary.fillRate * 100)`，快照里没有 fillRate 时印 `NaN%`。 */
    const rate = planFillRate(model)
    push(`- 埋词：计划 ${summary.plannedCells} 处，实际落在 ${summary.reachedCells} 处，**完成率 ${rate === null ? '未记录' : `${Math.round(rate * 100)}%`}**（每个词平均 ${summary.averagePlaces} 处，计划 ${summary.averagePlanned} 处）`)
  }
  if (model.gates !== null && model.gates !== undefined) {
    push(`- 闸门：**${model.gates.passed}/${model.gates.total}** 通过${model.gates.ok ? '' : `，未过：${model.gates.gates.filter(gate => !gate.pass).map(gate => gate.label).join('、')}`}`)
  }
  /* 写回口径. Unconditional: how many of this report's fields the listing table
     can store is a property of the field registry, not of whether a write ran.
     The counts come from `writebackSplit`, so they cannot disagree with the
     vocabulary — the previous wording lived only in the tool's stdout and never
     reached the file the user actually reads. */
  /* 2026-10-25（R-48）：`writable.groups` / `draftOnly.groups` 在为空时是空字符串，
     于是这一行会印出「（）、」这种**空括号** —— 实测 run 4e60241a 的报告：
        「…0 个只出草案、无写回路径（）」
     一段讲「写回口径」的关键句，后面跟一对空括号，读者会以为这里漏了一串字段名。

     空的时候要写明「无」，而不是把括号留着。 */
  {
    const listOrNone = (groups) => {
      const text = groups === null || groups === undefined ? '' : String(groups).trim()
      return text === '' ? '无' : text
    }
    push(`- 写回口径：本报告 **${model.writeback.total}** 个字段中，`
      + `**${model.writeback.writable.count}** 个可写回 listing（${listOrNone(model.writeback.writable.groups)}），`
      + `**${model.writeback.draftOnly.count}** 个只出草案、无写回路径（${listOrNone(model.writeback.draftOnly.groups)}）`)
  }
  /* Conditional, and driven only by what actually happened: a report must never
     announce a write it did not perform. */
  if (model.applyListing?.ok === true) {
    push(`- ✅ 本轮已写入 listing（版本 +1，${model.applyListing.applied} 个字段）`)
  } else if (model.applyListing?.ok === false) {
    push(`- ⚠️ 本轮尝试写入 listing 失败：${model.applyListing.error ?? '未知错误'}（报告已生成，但库内 listing 未改动）`)
  }
  /* Where 「优化前」 came from, named at the top because §四's per-field label is
     easy to skim past — and a "before" that is the plugin's own previous draft
     is a different claim from a "before" that is the live listing. */
  if (model.beforeSource !== null) {
    push(`- 优化前来源：${model.beforeSource.danger ? `**${model.beforeSource.phrase}**` : model.beforeSource.phrase}`)
  }
  push('')

  if (model.dropped.length > 0) {
    push('### ⚠️ 这次改写丢掉的词')
    push('')
    push('这些词当前 listing 里有、新文案里没有。读起来更好，但排名会在几周后慢慢掉 —— 现在是唯一便宜的修补时机。')
    push('')
    push(`| 关键词 | 层级 | 当前排名 |`)
    push(`| --- | --- | --- |`)
    for (const entry of model.dropped) push(`| ${cell(entry.keyword)} | ${cell(entry.tierLabel ?? entry.tier ?? '—')} | ${cell(entry.rank ?? '—')} |`)
    push('')
  }

  /* 二、产品概况 */
  push(`## ${sectionTitle('s2')}`)
  push('')
  if (model.productRows === null) {
    push('_没有关联到 ASIN 记录，本节跳过。_')
  } else {
    push('| 项目 | 值 |')
    push('| --- | --- |')
    for (const [label, value] of model.productRows) push(`| ${cell(label)} | ${cell(value)} |`)
    push('')
    if (model.marketplace.units !== undefined) {
      push(`计量习惯：长度用 **${model.marketplace.units.length}**、重量用 **${model.marketplace.units.weight}**、温度用 **${model.marketplace.units.temperature}**。`)
      push('')
    }
    if ((model.marketplace.habits ?? []).length > 0) {
      push('该站点的购买习惯（每条都标了依据）：')
      push('')
      for (const habit of model.marketplace.habits) push(`- ${habit.text}  \n  <sub>依据：${habit.source}</sub>`)
      push('')
    } else if (model.provisional === null) {
      push('_该站点没有记录购买习惯。_')
      push('')
    }
  }

  /* 三、埋词策略 */
  push(`## ${sectionTitle('s3')}`)
  push('')
  if (model.plan === null || model.plan === undefined) {
    push('_本轮没有生成全局计划。_')
  } else {
    push(`### 3.1 埋词位置（${model.plan.positions.length} 个，按权重降序）`)
    push('')
    push('| # | 位置 | 落点 | 权重 | 本轮是否写入 |')
    push('| --- | --- | --- | --- | --- |')
    model.plan.positions.forEach((position, index) => {
      const written = (model.plan.writtenPositions ?? []).includes(position.id)
      push(`| ${index + 1} | ${cell(position.label)} | ${cell(position.where)} | ${cell(position.weightLabel)} | ${written ? '✅' : '—'} |`)
    })
    push('')
    push('> Item Highlights 不在 SOP §三 的 11 个位置里 —— 该 SOP 早于这个字段。它 2026-07 才进注册表，是 Alexa for Shopping 的检索入口，所以列在这里。')
    push('')

    const matrix = model.plan.coverageMatrix
    push('### 3.2 埋词覆盖矩阵（计划 vs 实际）')
    push('')
    push(`每个词计划落 **${matrix.summary.averagePlanned}** 处，实际落 **${matrix.summary.averagePlaces}** 处。差值就是还能加深的空间。`)
    push('')
    push(`| 关键词 | 层级 | 主人 | ${matrix.positions.map(position => cell(position.label)).join(' | ')} | 实际 | 计划 | 差 |`)
    push(`| --- | --- | --- | ${matrix.positions.map(() => '---').join(' | ')} | --- | --- | --- |`)
    for (const row of matrix.rows) {
      const marks = matrix.positions.map(position => (row.cells[position.id] ? '✅' : '·'))
      push(`| ${cell(row.keyword)} | ${cell(row.tier ?? '未测')} | ${cell(labelForField(row.owner))} | ${marks.join(' | ')} | ${row.total} | ${row.plannedCount} | ${row.gap > 0 ? `**${row.gap}**` : '0'} |`)
    }
    push('')

    push('### 3.3 关键词分配（每个词一个主人 + 复用理由）')
    push('')
    push('| 关键词 | 主人 | 为什么放这里 | 支持位置（各自有理由） |')
    push('| --- | --- | --- | --- |')
    for (const entry of model.plan.allocation.entries) {
      const supporting = entry.supporting.length === 0
        ? '—'
        : entry.supporting.map(item => `${item.positionLabel}：${item.reason}`).join('<br>')
      push(`| ${cell(entry.keyword)} | ${cell(entry.ownerLabel)} | ${cell(entry.ownerReason)} | ${cell(supporting)} |`)
    }
    push('')
    /* The title's word-repeat rule is a *site* property, not a universal one. On
       a site whose lexicon declines it, the report must say so — otherwise the
       reader sees a title that "passed" a rule which was never applied. */
    const capacity = model.plan.allocation?.titleCapacity
    if (capacity) {
      if (capacity.applicable === false) {
        push(`**标题**：${capacity.note ?? '本站点不做单词重复约束'}`)
      } else {
        const spilled = capacity.rejected.length > 0
          ? `，让出 ${capacity.rejected.length} 个给五点（${capacity.rejected.join('、')}）`
          : ''
        push(`**标题的单词重复约束**：同一个词最多出现 **${capacity.limit}** 次。本轮保留 ${capacity.kept.length} 个词进标题${spilled}。`)
      }
      push('')
    }
    if (model.plan.allocation.violations.length > 0) {
      push('**分配冲突**')
      push('')
      for (const violation of model.plan.allocation.violations) push(`- ${violation.detail}`)
      push('')
    }
  }

  /* 四、逐字段 */
  push(`## ${sectionTitle('s4')}`)
  push('')
  if (model.rows.length === 0) {
    push('_本轮没有字段草稿。_')
  }
  /* 「没有发布登记」要说一次，**不是**每格说一次：75 个字段各印一句「没有实际发布值」
     会把这一节淹掉，而读者真正需要知道的是「还没有人登记过发布」（§6）。
     注意这一句说的是「没有登记」，不是「发布值是空的」。 */
  if (model.rows.length > 0 && model.activation.count === 0) {
    push('> 本轮**没有发布登记**，所以逐字段不印「实际发布值」—— 这不是「发布值是空的」，'
      + '是还没有人登记过发布（§6）。登记之后重出报告，这一节会逐个字段印出线上实际的值。')
    push('')
  }
  /* 2026-10-26（R-89，需求方指定）：逐字段的**主视图**先给一张五列表 ——
     序号 / 属性字段 / 优化前值 / 优化后值 / 优化后详细说明。
     分组明细留在后面：它们回答的是「这一格能不能直接贴进后台」，
     而这张表回答的是「这一轮到底改了什么」—— 两个问题不该挤进同一张表。 */
  if (model.rows.length > 0) {
    push('### 4.1 对照表（一屏看完这一轮改了什么）')
    push('')
    push('| 序号 | 属性字段 | 优化前值 | 优化后值 | 优化后详细说明 |')
    push('| --- | --- | --- | --- | --- |')
    model.rows.forEach((row, index) => {
      push(`| ${index + 1} | ${mdCell(row.label)}（\`${row.field}\`） | ${mdCell(row.before)} | ${mdCell(row.after)} | ${mdCell(row.rationale)} |`)
    })
    /* R-91：模板要求、但本轮没有草稿的字段 —— 一样占一行。**它们不是「没问题」，是「没写」。** */
    ;(model.templateMissing ?? []).forEach((item, index) => {
      push(`| ${model.rows.length + index + 1} | ${mdCell(item.label)}（\`${item.id}\`） | — | **（本轮没有草稿）** | `
        + `模板要求这一格${item.required ? '，且它是**必填**' : ''}${item.limit === null ? '' : `（上限 ${item.limit}）`} —— 本轮没有生成草稿`)
    })
    push('')
    if ((model.templateMissing ?? []).length > 0) {
      const requiredMissing = model.templateMissing.filter(item => item.required).length
      push(`> 这一轮覆盖 ${model.rows.length} / ${model.rows.length + model.templateMissing.length} 个模板字段，`
        + `缺 ${model.templateMissing.length} 个（其中必填 ${requiredMissing} 个）。`
        + '缺的那些**不是「不用管」**：报告把它们印出来，就是为了让「还差多少」有一个数字。')
      push('')
    }
  }
  for (const group of model.groups) {
    push(`### ${group.label}`)
    push('')
    for (const row of group.rows) {
      push(`#### ${row.label}${row.accepted ? ' ✅' : ''}`)
      push('')
      if (row.before !== null) {
        push(beforeLabelMarkdown(model.beforeSource))
        push('')
        push(fence(row.before))
        push('')
      }
      if (row.after !== null) {
        push(`**优化后**${row.publishable ? '（可直接复制粘贴到亚马逊后台）' : '（该字段不能通过表格上传，要人工在对应编辑器里填）'}`)
        push('')
        push(fence(row.after))
        push('')
      }
      /* 实际发布值（§28.2）。**只在真的登记过这个字段时印**，并且与草案逐字对比 ——
         读者要回答的问题是「线上现在是不是这份草案」，不是一个抽象的状态。 */
      if (row.published !== null) {
        push(`**实际发布值**（登记 \`${cell(row.published.publicationId)}\`，${cell(row.published.publishedAt)}，草案版本 ${row.published.draftVersion === null ? '未记' : `v${row.published.draftVersion}`}）`)
        push('')
        push(fence(String(row.published.value ?? '（发布的是空值）')))
        push('')
        if (row.published.agrees === true) push('> 与本轮草案**一致**。')
        else if (row.published.agrees === false) push('> ⚠️ 与本轮草案**不同** —— 线上不是这份草案的文本。')
        else push('> 本轮草案里**没有这个字段**（登记里多出来的），所以「一致不一致」问不出来。')
        push('')
      }
      /* 字段级置信度/风险（§28.2）。等级 + 全部理由：只印一条理由会让读者以为
         没有别的理由了。 */
      push(`> **置信度 ${row.confidence.label}**：${row.confidence.reasons.join('；')}　｜　`
        + `**风险 ${row.risk.label}**：${row.risk.reasons.join('；')}`)
      push('')
      if (row.rationale !== null) {
        push(`> **为什么这样改：** ${row.rationale}`)
        push('')
      }
      /* 预期紧跟 rationale：一句「为什么」、一句「改完看什么数」。
         反向指标单独一行，因为它是"没变好"最容易被误判成"没影响"的那一格。 */
      if (row.expected !== undefined && row.expected !== null) {
        push(`> **预期：** ${expectationLine(row.expected)}`)
        if (row.expected.watchFor !== null && row.expected.watchFor !== undefined) {
          push(`> **反向指标：** ${row.expected.watchFor}`)
        }
        push(`> **依据：** ${row.expected.basis}`)
        push('')
      }
      if (row.keywords.length > 0) {
        push(`> **植入了：** ${row.keywords.map(entry => (typeof entry === 'string' ? entry : entry.keyword)).join('、')}`)
        push('')
      }
      if (row.needsConfirmation) {
        push('> ⚠️ 这一项是**事实**不是文案。模型只能提议，必须由人对着实物确认后再填。')
        push('')
      }
      for (const violation of row.violations) {
        push(`- **${SEVERITY_LABEL[violation.severity] ?? violation.severity}** ${violation.title}（${violation.ruleId}，依据 ${violation.source}）：${violation.messages.join('；')}`)
      }
      if (row.violations.length > 0) push('')
      /* 证据跳转（§28.4）：这个字段的结论依据哪几类冻结证据。空的时候不印 ——
         没有证据包时第十二节与附录会说清楚，不必每格重复。 */
      const evidenceRows = evidenceForField(model, row.field)
      if (evidenceRows.length > 0) {
        push(`<sub>依据的证据这一类：${evidenceRows.map(entry => `[${entry.label}](#ev-${entry.kind})`).join('、')}</sub>`)
        push('')
      }
    }
  }

  /* 五、属性 */
  push(`## ${sectionTitle('s5')}`)
  push('')
  push(`已填 **${model.attributes.filledCount}/${model.attributes.target}**。属性权重 2026 起已超过后台搜索词，每个空字段是 COSMO 知识图谱的一个断连。`)
  push('')
  push('| 属性 | 当前值 | 需要具体化 |')
  push('| --- | --- | --- |')
  for (const row of model.attributeRows) {
    push(`| ${cell(row.label)} | ${row.value === null ? '❌ 空' : cell(row.value)} | ${row.specific ? '是' : ''} |`)
  }
  push('')
  if (model.attributes.empty.length > 0) {
    push(`**还空着的 ${model.attributes.empty.length} 项：** ${model.attributes.empty.map(id => ATTRIBUTES[id]?.label ?? id).join('、')}`)
    push('')
  }

  /* 六、可粘贴区块。`model.pasteable` —— 模型里算一次，HTML 读同一份。 */
  const pasteable = model.pasteable
  if (pasteable.length > 0) {
    push(`## ${sectionTitle('s6')}`)
    push('')
    push('以下文本块可以逐段复制进卖家后台，不需要再改。')
    push('')
    for (const row of pasteable) {
      push(`**【${row.label}】**`)
      push('')
      push(fence(row.after))
      push('')
    }
  }

  /* 七、非上传字段 */
  const surfaceRows = model.surfaceRows
  if (surfaceRows.length > 0) {
    push(`## ${sectionTitle('s7')}`)
    push('')
    push('这些字段不在上架表格里，各有自己的编辑入口。文案是草案，需要人工搬过去。')
    push('')
    for (const row of surfaceRows) {
      push(`**【${row.label}】**${row.accepted ? '' : '（未采纳）'}`)
      push('')
      push(fence(row.after))
      push('')
      if (row.rationale !== null) push(`> ${row.rationale}`)
      if (row.rationale !== null) push('')
    }
  }

  /* 八、合规校验 */
  push(`## ${sectionTitle('s8')}`)
  push('')
  if (model.validation === null || model.validation === undefined) {
    push('_本轮没有留下校验结果。_')
  } else if (model.validation.violations.length === 0) {
    /* "全部通过" is only true if every rule actually ran. A rule the site's
       script made undecidable is neither a pass nor a fail, so say so here. */
    const skippedCount = (model.validation.skipped ?? []).length
    push(skippedCount === 0
      ? '机检规则全部通过。'
      : `机检规则没有发现违规，但其中 **${skippedCount}** 条在本站点不适用、**没有执行** —— 见 8.2，不要把「不适用」读成「通过」。`)
  } else {
    push('| 严重度 | 规则 | 字段 | 说明 | 依据 |')
    push('| --- | --- | --- | --- | --- |')
    for (const violation of model.validation.violations) {
      push(`| ${SEVERITY_LABEL[violation.severity] ?? violation.severity} | ${cell(violation.ruleId)} | ${cell(labelForField(violation.field))} | ${cell(violation.messages.join('；'))} | ${cell(violation.source)} |`)
    }
  }
  push('')

  if (model.gates !== null && model.gates !== undefined) {
    push('### 8.1 六道闸门')
    push('')
    push('| 闸门 | 结果 | 说明 |')
    push('| --- | --- | --- |')
    for (const gate of model.gates.gates) push(`| ${cell(gate.label)} | ${gate.pass ? '✅ 通过' : '❌ 未过'} | ${cell(gate.detail)} |`)
    push('')
    push('> 闸门与规则是两件事：规则判「合不合法」，闸门判「全不全」。一份完全合法的文案可以只写了 11 个章节里的 4 个。')
    push('')
  }

  /* 8.2 — rules that could not be judged on this site. Stated, not silently
     passed: a rule that never ran must never read as a rule that passed. */
  const skipped = model.validation?.skipped ?? []
  if (skipped.length > 0) {
    push('### 8.2 本站点不适用的规则（**不是通过**）')
    push('')
    push('下面这些规则在本站点无法判定，因此**没有执行**。它们既不是通过，也不是违规 —— 把「不适用」读成「通过」正是本报告要避免的事。')
    push('')
    push('| 规则 | 字段 | 严重度 | 原因 | 依据 |')
    push('| --- | --- | --- | --- | --- |')
    for (const entry of skipped) {
      push(`| ${cell(entry.ruleId)} | ${cell(labelForField(entry.field))} | ${SEVERITY_LABEL[entry.severity] ?? entry.severity} | ${cell(entry.reason)} | ${cell(entry.source)} |`)
    }
    push('')
  }

  push('### 8.3 这份报告不判定的事（Agent 审阅清单）')
  push('')
  push('下面这些是规则文档要求、但只能由模型或人来判断的。机检通过**不代表**这些也通过。'
    + '工作台的「校验体系 → Agent 审阅」面板逐项记结论（可以逐字段），每条结论必须引用证据。')
  push('')
  push('| 检查项 | 依据 | 要问的问题 | 只能人判 |')
  push('| --- | --- | --- | --- |')
  for (const check of model.llmOnly) push(`| ${cell(check.label ?? check.id)}（${cell(check.id)}） | ${cell(check.source)} | ${cell(check.ask)} | ${check.needsHuman === true ? '是' : ''} |`)
  push('')

  /* 九、预算 */
  push(`## ${sectionTitle('s9')}`)
  push('')
  if (model.budgets.length === 0) {
    push('_没有可测量的字段。_')
  } else {
    push('| 字段 | 用量 | 上限 | 单位 | 来源 |')
    push('| --- | --- | --- | --- | --- |')
    for (const row of model.budgets) {
      const unit = row.unit === 'bytes' ? '字节' : '字符'
      push(`| ${cell(row.label)} | ${row.used} | ${row.max}${row.over ? ' ❌' : ''} | ${unit} | ${row.limitSource === 'documented' ? '文档规定' : '经验值'} |`)
    }
    push('')
    push('> 后台搜索词按**字节**算，其他按**字符**算。一个中文字 3 字节，所以 249 字节装不下 249 个中文字 —— 超了亚马逊可能整个字段都不索引。')
    push('')
    push('> 「经验值」是我们给的区间，不是文档规定的上限。')
    push('')
  }

  /* 十、事实台账 */
  if (model.hasFactLedger === true) {
    push(`## ${sectionTitle('s10')}`)
    push('')
    const ledger = model.plan.factLedger
    push(`记录了 **${ledger.summary.total}** 个事实，每个事实只允许一个取值。`)
    push('')
    if (ledger.conflicts.length > 0) {
      push('### ⚠️ 事实冲突')
      push('')
      for (const conflict of ledger.conflicts) push(`- **${conflict.label}**：${conflict.values.join(' / ')} —— ${conflict.detail}`)
      push('')
    } else {
      push('没有冲突：同一个事实在各字段里的取值一致。')
      push('')
    }
    const withOccurrences = ledger.rows.filter(row => row.occurrences.length > 0)
    if (withOccurrences.length > 0) {
      push('| 事实 | 取值 | 出现位置 |')
      push('| --- | --- | --- |')
      for (const row of withOccurrences) {
        push(`| ${cell(row.label)} | ${cell(row.value)} | ${cell(row.occurrences.map(occurrence => labelForField(occurrence.field)).join('、'))} |`)
      }
      push('')
    }
  }

  /* 十一、人工必填 */
  push(`## ${sectionTitle('s11')}`)
  push('')
  push('这些采集不到、也推断不出来。填错变体关系或类目会影响整组链接，所以单独列出来。')
  push('')
  push('| 字段 | 说明 | 库内状态 |')
  push('| --- | --- | --- |')
  for (const field of model.manualFields) push(`| ${cell(field.label)} | ${cell(field.why)} | ${cell(manualStatusLabel(field))} |`)
  push('')

  /* 十二、上架操作清单（F13-09）
     这一节以前是**六条写死的散文**，不随这一轮的内容变：它说不出「哪几个字段、去哪儿、
     什么状态」。现在每一行都来自 `model.delivery`（`buildDelivery` 的产出），而那份
     清单的每一条状态都由内容重算 —— 「已登记」读的是发布登记里 `published` 的键。 */
  push(`## ${sectionTitle('s12')}`)
  push('')
  if (model.delivery === null || model.delivery === undefined || model.delivery.ok !== true) {
    push('_交付边界读不出来（这一份报告没有挂在轮次上）—— 这不是「没有要交付的东西」。_')
    push('')
  } else {
    const delivery = model.delivery
    push(`这一轮 **${delivery.counts.operations}** 条操作：`
      + `可复制粘贴 ${delivery.counts.ready} · 去独立编辑器 ${delivery.counts.editor} · `
      + `草案未采纳（不要去改）${delivery.counts.notAccepted} · 本轮没有生成 ${delivery.counts.noText} · `
      + `必须人工填 ${delivery.counts.humanRequired} · 已登记发布 ${delivery.counts.registered}`)
    push('')
    push('每一条都是「去哪儿、做什么」。**勾选状态不落库** —— 报告是一份静态文档，'
      + '而「人做过什么」的持久事实在模块 14 的发布登记里（见 12.2）。'
      + '已经登记过发布的那些字段，下面直接画成勾上的。')
    push('')
    for (const operation of delivery.operations) {
      push(`- [${operation.status === 'registered' ? 'x' : ' '}] **${operation.fieldLabel}**`
        + `（${operation.surfaceLabel}）— ${operation.action}　\`${operation.statusLabel}\``)
    }
    push('')

    push('### 12.1 交付边界：哪些字段是这个插件给的，哪些要人填')
    push('')
    push('| 类别 | 条数 | 这一轮的具体字段 |')
    push('| --- | --- | --- |')
    push(`| 插件提供（这一轮有草案） | ${delivery.boundary.plugin.count} | ${cell(delivery.boundary.plugin.note)} |`)
    push(`| 插件**不提供** | ${delivery.boundary.humanOnly.count} | ${cell(delivery.boundary.humanOnly.fields.map(id => labelForField(id)).join('、'))} |`)
    push(`| 插件会提供、**这一轮没有生成** | ${delivery.boundary.notGenerated.count} | ${cell(delivery.boundary.notGenerated.fields.map(field => labelForField(field)).join('、'))} |`)
    push('')
    push('> 第二行与第三行**不是一件事**：第二行是「本仓没有这些字段的来源」（SKU / 库存 / 价格 / 类目 / '
      + '变体 / 浏览节点 / 目标人群，采集不到也推断不出来，只能人填）；第三行是「插件本来会产出这些字段的草案，'
      + '但这一轮没有生成它」（没有输入，或者这一轮的模式/模型没有写到它）。把这两句压成一句，'
      + '读者就会去后台找一个插件根本不提供的字段的值。')
    push('')
    if (delivery.unmappedSurfaces.length > 0) {
      push(`⚠️ 有 ${delivery.unmappedSurfaces.length} 个 section 没有登记交付落点（${delivery.unmappedSurfaces.join('、')}）——`
        + '它们不会被归进任何一个「上架表格」里，这是注册表变了而落点表没跟上。')
      push('')
    }

    push('### 12.2 发布登记：接受草案 ≠ 已发布')
    push('')
    push('> **接受草案 ≠ 已发布。** 这份报告里的文字，在你到卖家后台改完、并登记发布之前，'
      + '线上**一个字都没变**。这个插件不会在 Seller Central 点任何按钮，也不调任何发布接口 ——'
      + '它只记录你做了什么。')
    push('')
    const registration = delivery.registration
    push(`登记入口：工作台「优化 → 发布记录」的表单（页面会预填运行 id 与草案版本）。`)
    push('')
    push(`- 运行 id：\`${cell(registration.runId)}\``)
    push(`- 草案版本：${registration.draftVersionKnown ? `\`v${registration.draftVersion}\`` : '_读不到（这不是「版本是 0」）_'}`)
    push(`- 已登记的字段：${registration.registered.count} 个`
      + (registration.registered.count === 0
        ? '（**一条发布都还没有登记过** —— 这不是「登记里没有字段」）'
        : `（最近一条 ${cell(registration.registered.latestId)}，${cell(registration.registered.latestAt)}）`))
    push('')
    push('> 下面这几句是**经验**，不是由这一轮的内容推出来的：改动前先截图存档（万一要回滚）；'
      + '每改完一个字段保存一次；改完 24 小时看是否触发审核、48 小时看排名与广告数据；'
      + '有广告活动的 ASIN 改完要检查广告组的关键词质量分。')
    push('')

    /* 12.3 —— 实际发布值（§28.2 第三件）。这一节回答「登记里到底填了什么」，
       以及 §6 那个**登记时冻结**的偏离判定。两者不同源，措辞必须分开：
       冻结的那份是权威（登记之后草案还会被人改），逐字段的现时对比回答的是
       「线上现在是不是这一版」。 */
    if (model.activation.count > 0) {
      const activation = model.activation
      push('### 12.3 实际发布值（从发布登记读回来）')
      push('')
      push(`- 登记 **${activation.count}** 条${activation.latest === null ? '' : `，最近一条 \`${cell(activation.latest.id)}\`（${cell(activation.latest.publishedAt ?? '')}，草案版本 ${activation.latest.draftVersion === null ? '未记' : `v${activation.latest.draftVersion}`}）`}`)
      if (activation.deviation !== null) {
        const deviation = activation.deviation
        push(`- §6 的偏离判定（**登记时冻结**，不随今天的草案重算）：`
          + `${activation.deviated ? `**偏离**（${activation.deviationRule === 'core-field' ? '改了核心字段' : '改动超过阈值'}）` : '未偏离'}`
          + `，改动 **${deviation.changedCount}/${deviation.total}** 个字段（${Math.round((deviation.ratio ?? 0) * 100)}%）`
          + `${(deviation.coreChanged ?? []).length === 0 ? '' : `，核心字段：${deviation.coreChanged.map(field => labelForField(field)).join('、')}`}`)
      } else {
        push('- §6 的偏离判定：这条登记**没有冻结的差异结果**（不是「没有偏离」）')
      }
      if (activation.uncovered.length > 0) {
        push(`- 发布里出现、批准草案**没有覆盖**的字段（记录但不计入偏离比值）：${activation.uncovered.join('、')}`)
      }
      push('')
      push('| 字段 | 本轮草案 | 实际发布 | 一致 | 登记 |')
      push('| --- | --- | --- | --- | --- |')
      for (const entry of activation.entries) {
        const agrees = entry.agrees === true ? '✅ 一致' : (entry.agrees === false ? '⚠️ 不同' : '本轮未覆盖')
        push(`| ${cell(labelForField(entry.field))} | ${cell(brief(entry.draftAfter))} | ${cell(brief(entry.value))} | ${agrees} | ${cell(entry.publicationId ?? '—')} @ ${cell(entry.publishedAt ?? '—')} |`)
      }
      push('')
    }
  }

  /* 附录、证据包（§28.4 的证据跳转落点）。这一节列出这一轮**冻结**的十一类证据：
     每一类的状态（冻结 / 不存在 / 未建模）、观测时间、来源、条数。上面每个字段的
     「依据的证据这一类」链接就落在这里的锚点上。 */
  if (model.evidencePack !== null) {
    const pack = model.evidencePack
    push(`## ${sectionTitle('s-evidence')}`)
    push('')
    push(`冻结于 ${pack.frozenAt === null ? '读不到' : pack.frozenAt}${pack.lateFreeze ? '（**补冻**：晚于这一轮收尾）' : ''}。`
      + (pack.counts === null ? '' : `十一类里：冻结 ${pack.counts.frozen} · 不存在 ${pack.counts.absent} · 未建模 ${pack.counts.notModelled}`
        + (pack.missing.length > 0 ? `；包里缺 ${pack.missing.length} 类（${pack.missing.join('、')}）` : '；十一类齐全') + '。'))
    push('')
    push('| 类 | 状态 | 观测时间 | 来源 | 条数 |')
    push('| --- | --- | --- | --- | --- |')
    for (const row of pack.rows) {
      push(`| ${cell(row.label)} | ${evidenceStatusLabel(row.status)} | ${row.at === null ? '无日期' : cell(row.at)} | ${cell(row.source ?? '—')} | ${row.count === null ? '不适用' : row.count} |`)
    }
    push('')
    push('> 「不存在」（absent）与「0 条」不是一件事：前者是这个对象上没有可冻结的东西，'
      + '后者是读过了、答案是 0。「未建模」是本仓没有这一类的来源 —— 三种说法都不许互相代替。')
    push('')
  }

  /* 十三、自检总表 */
  push(`## ${sectionTitle('s13')}`)
  push('')
  const checks = selfCheck(model)
  push('| 检查项 | 标准 | 结果 | 状态 |')
  push('| --- | --- | --- | --- |')
  for (const check of checks) {
    push(`| ${cell(check.item)} | ${cell(check.standard)} | ${cell(check.result)} | ${checkMark(check)} |`)
  }
  push('')
  push('> 状态「—」= **这一项没有执行**（不是通过，也不是不达标）—— 与校验闸门的 `unverified` 是同一件事。')
  push('')

  push('---')
  push('')
  push(`_生成时间：${new Date().toISOString()}｜规则集 ${model.rules?.version ?? '—'}｜埋词位置 ${planPositionText(model)}｜字段词汇 ${Object.keys(FIELDS).length} 项 + ${REQUIRED_ATTRIBUTE_TARGET} 项属性_`)

  return lines.join('\n')
}

const statusLabel = (status) => ({ done: '已收尾', running: '进行中', failed: '失败', draft: '草稿' }[status] ?? status ?? '—')

/* `manualStatusLabel` 现在住在 `delivery.js` —— 交付边界才是「哪些字段要人填」这个问题
   的属主，而报告第十一节与交付清单必须用同一句话回答它（同一件事两套措辞，
   读者会以为是两件事）。本文件从那里 import，不再自己留一份。 */

/**
 * 一个**读数**：有数就是数，没数就是 `null` —— 没有第三种可能。
 *
 * `Number.isFinite(Number(v))` 这条路本仓栽过：`Number(null)` 是 0 且
 * `Number.isFinite(0)` 为真，于是「没有值」被写成真的 0。所以先判空再转。
 */
function readingOrNull(value) {
  if (value === null || value === undefined) return null
  if (typeof value === 'string' && value.trim() === '') return null
  const num = Number(value)
  return Number.isFinite(num) ? num : null
}

/**
 * `plan.coverageMatrix.summary.fillRate` —— **埋词完成率的唯一读取入口**。
 *
 * 同一个值在四张表上被印（Markdown / HTML 的结论一节、自检总表、Excel 结论表），
 * 以前四处各写一遍 `Math.round(summary.fillRate * 100)`。只修一处，另外三处就会
 * 在「这一轮快照里没有 fillRate」时印出 `NaN%` —— 一个既不是 0、也不是「未测」的
 * 东西。所以读到这里：`null` 表示**没有这个读数**，四个读者各自用它的话说清楚。
 */
function planFillRate(model) {
  return readingOrNull(model?.plan?.coverageMatrix?.summary?.fillRate)
}

/**
 * 计划里有几个埋词位置。`null` = 这一轮没有计划（或快照里没有位置表）——
 * **不是 0 个**：0 个位置是一句关于计划内容的话，没有计划时它没资格说。
 */
function planPositionCount(model) {
  const positions = model?.plan?.positions
  return Array.isArray(positions) ? positions.length : null
}

/**
 * 页眉/页脚里那一格的话。四处（两种渲染 × 头/尾）共用一句 —— 各写一遍
 * 「计数为空就兜成 0」的模板，就是同一份报告在不同位置对同一件事给出两种说法
 * 的那种结构。
 */
const planPositionText = (model) => {
  const count = planPositionCount(model)
  return count === null ? '未记录' : `${count} 个`
}

/**
 * The 必检项 table from the docs, plus the fields this round added.
 *
 * Every threshold is read from its authority — `GLOBAL_LIMITS`, or the length of
 * the field list it counts — rather than typed in. The table used to hard-code
 * `5` / `5` / `5` / `7`, so editing `GLOBAL_LIMITS.bulletsMax` changed the
 * budgets and the gates but left this self-check reporting the old number: one
 * fact, two sources, silently disagreeing.
 *
 * ## 第三态：`unverified`（2026-10-25）
 *
 * 这张表原先只有「✅ 通过 / ❌ 不通过」两态，于是**没执行**的检查掉进了 ❌：
 * 完成率读不到时，那一格按 0 参与了「≥ 0.6」的比较 → 读者看到「埋词完成率 ❌」，
 * 而那是一个**没有发生过的判定**。「未测」不是「不达标」，也不是「通过」——
 * 与 `validate.js` 三道闸门修的是同一个病，所以用同一个字段名 `unverified: true`：
 * `result` 印「—」，`ok: false`（未判定绝不能进通过率）。反过来说，真读数
 * （含真的 0、真的低）仍然走 ✅/❌，不许被洗成「未测」。
 */
function selfCheck(model) {
  const fields = model.afterFields
  const budgetOf = (field) => model.budgets.find(row => row.field === field) ?? null
  const titleBudget = budgetOf('title')
  const backendBudget = budgetOf('search_terms')
  const highlightsBudget = budgetOf('item_highlights')
  const bullets = BULLET_FIELDS.filter(field => fields[field])
  const qa = Object.keys(fields).filter(field => field.startsWith('qa_'))
  const alts = Object.keys(fields).filter(field => field.startsWith('image_alt'))
  const aplus = Object.keys(fields).filter(field => field.startsWith('aplus_'))
  /* 这两项是「有输入才算得出」的读数：台账不在就没有冲突可数，计划里没有
     `fillRate` 就没有完成率可判。两者都不许兜成 0 / 0%。 */
  const fillRate = planFillRate(model)
  const conflicts = model?.plan?.factLedger?.conflicts
  const conflictCount = Array.isArray(conflicts) ? conflicts.length : null

  return [
    { item: '标题字符', standard: `≤${titleBudget?.max ?? GLOBAL_LIMITS.titleMax}`, result: titleBudget === null ? '未写' : `${titleBudget.used}`, ok: titleBudget !== null && !titleBudget.over },
    { item: '五点条数', standard: `${GLOBAL_LIMITS.bulletsMax} 条`, result: `${bullets.length}`, ok: bullets.length === GLOBAL_LIMITS.bulletsMax },
    { item: '五点格式', standard: '首字母大写 + 冒号', result: bullets.length > 0 ? '见逐字段校验' : '未写', ok: bullets.length === GLOBAL_LIMITS.bulletsMax },
    { item: '后台搜索词字节', standard: `≤${backendBudget?.max ?? GLOBAL_LIMITS.backendMaxBytes} 字节`, result: backendBudget === null ? '未写' : `${backendBudget.used}`, ok: backendBudget !== null && !backendBudget.over },
    { item: '产品亮点字符', standard: `≤${highlightsBudget?.max ?? GLOBAL_LIMITS.itemHighlightsMax}`, result: highlightsBudget === null ? '未写' : `${highlightsBudget.used}`, ok: highlightsBudget !== null && !highlightsBudget.over },
    { item: '属性填写率', standard: `${model.attributes.target} 项`, result: `${model.attributes.filledCount}/${model.attributes.target}`, ok: model.attributes.complete },
    { item: 'A+ 模块', standard: `≥${GLOBAL_LIMITS.aplusModules} 个`, result: `${aplus.length}`, ok: aplus.length >= GLOBAL_LIMITS.aplusModules },
    { item: 'Q&A 对数', standard: `≥${GLOBAL_LIMITS.qaMin} 对`, result: `${qa.length}`, ok: qa.length >= GLOBAL_LIMITS.qaMin },
    { item: '图片 Alt Text', standard: `${IMAGE_ALT_FIELDS.length} 项`, result: `${alts.length}`, ok: alts.length >= IMAGE_ALT_FIELDS.length },
    { item: '无阻断项', standard: '0 项', result: `${model.counts.block}`, ok: model.counts.block === 0 },
    /* 台账不在 → 这一项**没有执行**。以前冲突数缺失时兜成 0 再判等于 0：
       一个没跑过的检查，算出来的正好是「0 处冲突 ✅」。 */
    conflictCount === null
      ? { item: '事实一致', standard: '0 处冲突', result: '—', ok: false, unverified: true }
      : { item: '事实一致', standard: '0 处冲突', result: `${conflictCount}`, ok: conflictCount === 0 },
    /* 完成率读不到 → 未测（不是「0%，不达标」）。以前缺失时按 0 参与比较。 */
    fillRate === null
      ? { item: '埋词完成率', standard: '越高越好', result: '—', ok: false, unverified: true }
      : { item: '埋词完成率', standard: '越高越好', result: `${Math.round(fillRate * 100)}%`, ok: fillRate >= 0.6 },
  ]
}

/**
 * 自检行的状态 —— **三态只在这一处判定**。
 *
 * 三种渲染（Markdown / HTML / Excel）各写一遍 `check.ok ? … : …`，就是同一行在
 * 三种格式里可能给出三种结论的那种结构。所以判定收在这里，渲染层只负责把
 * `ok / fail / unverified` 翻译成自己的记号。
 */
function checkState(check) {
  if (check.unverified === true) return 'unverified'
  return check.ok === true ? 'ok' : 'fail'
}

/** 三态 → Markdown / HTML 的记号。`unverified` 印「—」：既不是勾，也不是叉。 */
const checkMark = (check) => ({ unverified: '—', ok: '✅', fail: '❌' })[checkState(check)]

/** 三态 → Excel 的说法。「未测」要能被人读，不是给眼睛扫的记号。 */
const checkLabel = (check) => ({ unverified: '未测', ok: '通过', fail: '未通过' })[checkState(check)]

/* ── HTML ──────────────────────────────────────────────────────────────────── */

const REPORT_CSS = [
  'body{font-family:system-ui,-apple-system,"Segoe UI",sans-serif;line-height:1.7;color:#1f2328;background:#fff;margin:0;padding:32px 20px}',
  '.wrap{max-width:1000px;margin:0 auto}',
  'h1{font-size:24px;font-weight:600;margin:0 0 8px}h2{font-size:18px;font-weight:600;margin:36px 0 12px;padding-bottom:6px;border-bottom:1px solid #e5e7eb}',
  'h3{font-size:15px;font-weight:600;margin:24px 0 8px}h4{font-size:14px;font-weight:600;margin:18px 0 6px}',
  '.meta{color:#57606a;font-size:13px;margin:0 0 4px}',
  'table{border-collapse:collapse;width:100%;margin:12px 0;font-size:13px}',
  'th,td{border:1px solid #d8dee4;padding:6px 9px;text-align:left;vertical-align:top}',
  'th{background:#f6f8fa;font-weight:600}',
  'pre{background:#f6f8fa;border:1px solid #d8dee4;border-radius:6px;padding:12px;overflow-x:auto;font-size:13px;white-space:pre-wrap;word-break:break-word}',
  'code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace}',
  'blockquote{margin:10px 0;padding:8px 14px;border-left:3px solid #d0d7de;background:#f6f8fa;color:#424a53;font-size:13px}',
  '.warn-box{border:1px solid #d4a72c;background:#fff8e5;border-radius:6px;padding:12px 16px;margin:16px 0}',
  '.bad{color:#a40e26}.good{color:#1a7f37}',
  '.ok{color:#1a7f37;font-weight:600}.no{color:#a40e26;font-weight:600}',
  'ul{margin:8px 0;padding-left:22px}li{margin:4px 0}',
  '.pill{display:inline-block;padding:1px 7px;border-radius:10px;background:#eef2f6;font-size:12px;color:#424a53}',
  /* §28.4 的目录与字段判据两处的观感：目录是一块独立卡片，字段级判据是淡底一行。 */
  '.toc{border:1px solid #d8dee4;border-radius:6px;padding:8px 16px;margin:16px 0;font-size:13px}',
  '.toc h2{font-size:14px;margin:4px 0 8px;border:0;padding:0}',
  '.toc ol{margin:0;padding-left:20px}.toc li{margin:2px 0}',
  '.provenance td.pv{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px}',
  '.assess{font-size:13px;color:#424a53;background:#f6f8fa;border-radius:6px;padding:6px 10px;margin:8px 0}',
].join('')

const htmlTable = (headers, rows) => {
  const head = headers.map(header => `<th>${esc(header)}</th>`).join('')
  const body = rows.map(row => `<tr>${row.map(value => `<td>${value}</td>`).join('')}</tr>`).join('')
  return `<table><thead><tr>${head}</tr></thead><tbody>${body}</tbody></table>`
}

/**
 * The HTML rendering.
 *
 * Self-contained on purpose: no external stylesheet, font or script, so the file
 * still renders correctly opened from disk with no network. A report that needs
 * a CDN to look right is a report that looks broken on a plane.
 */
export function renderHtml(model) {
  const parts = []
  const push = (...values) => parts.push(...values)

  push('<!DOCTYPE html><html lang="zh-CN"><head><meta charset="utf-8">')
  push('<meta name="viewport" content="width=device-width,initial-scale=1">')
  push(`<title>Listing 优化报告 — ${esc(model.asin?.asin ?? model.run?.asin ?? '')}</title>`)
  push(`<style>${REPORT_CSS}</style></head><body><div class="wrap">`)

  push(`<h1>Listing 优化报告 — ${esc(model.asin?.asin ?? model.run?.asin ?? '（未指定 ASIN）')}</h1>`)
  push(`<p class="meta">站点：${esc(model.marketplace.label)}（${esc(model.marketplace.code)}）｜优化轮次：#${esc(model.run?.id ?? '—')}｜状态：${esc(statusLabel(model.run?.status))}</p>`)
  push(`<p class="meta">规则集：${esc(model.rules?.version ?? '—')}｜埋词位置：${planPositionText(model)}｜字段：${model.rows.length} 个</p>`)

  if (model.provisional !== null) {
    push(`<div class="warn-box"><strong>⚠️ 站点规则未核验</strong><p>${esc(model.provisional.text)}</p></div>`)
  }
  /* The keyword-lexicon disclosure, kept separate from the site-rules one above.
     Carries both the support-position caveat and the title-rule disclosure. */
  if (model.lexicon?.note || model.lexicon?.repeatNote) {
    const body = [model.lexicon.note, model.lexicon.repeatNote].filter(Boolean).map(text => `<p>${esc(text)}</p>`).join('')
    push(`<div class="warn-box"><strong>⚠️ 关键词词法未核验</strong>${body}</div>`)
  }

  /* 目录（§28.4）。**锚点与条目同源**：条目来自 `model.sections`，而每节的 `<h2>`
     用的是同一张表的 id —— 所以不可能出现「目录里有、正文里没有」的死链接。 */
  push(`<nav class="toc"><h2 id="toc">${esc(TOC_TITLE)}</h2><ol>`)
  for (const section of model.sections) push(`<li><a href="#${section.id}">${esc(section.title)}</a></li>`)
  push('</ol></nav>')

  /* ── F14-10 导出件头信息 ─────────────────────────────────────────────────────
     每行带 `id="eh-<row.id>"`，值单独放在 `<td class="pv">` 里 —— 与 provenance 表
     同一套记号，所以「先切出那一格再读」在两种文档上是同一种读法（整份 HTML 里
     include 一个标签是结构性永真，那种断言本仓已经栽过）。 */
  push(`<h2 id="s-export">${esc(sectionTitle('s-export'))}</h2>`)
  push('<table class="provenance"><thead><tr><th>字段</th><th>值</th><th>这一格是怎么来的</th></tr></thead><tbody>')
  for (const row of model.exportHeader.rows) {
    push(`<tr id="eh-${esc(row.id)}"><td>${esc(row.label)}</td><td class="pv">${esc(row.value)}</td><td>${esc(row.note ?? '')}</td></tr>`)
  }
  push('</tbody></table>')
  /* 与 Markdown 同一句：`freshness.statement` —— 两处念一份，不会各说各的。 */
  push(`<div class="warn-box"><strong>⚠️ ${esc(model.freshness.label)}</strong><p>${esc(model.freshness.statement)}</p></div>`)

  /* 摘要四字段（§28.2）。值单独放在 `<td class="pv">`，并带 `id="pv-<field>"`
     —— 「先切出那一格再读」是这一节能被断言的前提（整份 HTML 里 include 一个标签
     是结构性永真）。 */
  push(`<h2 id="s-provenance">${esc(sectionTitle('s-provenance'))}</h2>`)
  push('<table class="provenance"><thead><tr><th>字段</th><th>值</th><th>这一格是怎么来的</th></tr></thead><tbody>')
  for (const row of model.provenance.rows) {
    push(`<tr id="pv-${esc(row.id)}"><td>${esc(row.label)}</td><td class="pv">${esc(row.value)}</td><td>${esc(row.note ?? '')}</td></tr>`)
  }
  push('</tbody></table>')

  /* 一 */
  push(`<h2 id="s1">${esc(sectionTitle('s1'))}</h2><ul>`)
  push(`<li>采纳 <strong>${model.accepted.length}</strong> 个字段，未采纳 ${model.rejected.length} 个，待定 ${model.pending.length} 个</li>`)
  push(`<li>阻断 <strong class="${model.counts.block === 0 ? 'good' : 'bad'}">${model.counts.block}</strong> 项，警告 <strong>${model.counts.warn}</strong> 项</li>`)
  push(`<li>属性填写 <strong>${model.attributes.filledCount}/${model.attributes.target}</strong></li>`)
  if (model.plan?.coverageMatrix) {
    const summary = model.plan.coverageMatrix.summary
    /* 与 Markdown 同一入口、同一句「未记录」（两种渲染对同一格不许说两句话）。 */
    const rate = planFillRate(model)
    push(`<li>埋词：计划 ${summary.plannedCells} 处，实际 ${summary.reachedCells} 处，<strong>完成率 ${rate === null ? '未记录' : `${Math.round(rate * 100)}%`}</strong>（平均 ${summary.averagePlaces} 处 / 计划 ${summary.averagePlanned} 处）</li>`)
  }
  if (model.gates) {
    push(`<li>闸门：<strong>${model.gates.passed}/${model.gates.total}</strong> 通过</li>`)
  }
  /* 写回口径 — unconditional (registry property), then the write itself only if
     it actually happened. Same two facts as the Markdown rendering. */
  push(`<li>写回口径：本报告 <strong>${model.writeback.total}</strong> 个字段中，<strong>${model.writeback.writable.count}</strong> 个可写回 listing（${esc(model.writeback.writable.groups)}），<strong>${model.writeback.draftOnly.count}</strong> 个只出草案、无写回路径（${esc(model.writeback.draftOnly.groups)}）</li>`)
  if (model.applyListing?.ok === true) {
    push(`<li class="good">✅ 本轮已写入 listing（版本 +1，${model.applyListing.applied} 个字段）</li>`)
  } else if (model.applyListing?.ok === false) {
    push(`<li class="bad">⚠️ 本轮尝试写入 listing 失败：${esc(model.applyListing.error ?? '未知错误')}（报告已生成，但库内 listing 未改动）</li>`)
  }
  push('</ul>')

  if (model.dropped.length > 0) {
    push('<h3>⚠️ 这次改写丢掉的词</h3>')
    push('<p>这些词当前 listing 里有、新文案里没有。读起来更好，但排名会在几周后慢慢掉。</p>')
    push(htmlTable(['关键词', '层级', '当前排名'], model.dropped.map(entry => [esc(entry.keyword), esc(entry.tierLabel ?? entry.tier ?? '—'), esc(entry.rank ?? '—')])))
  }

  /* 二 */
  push(`<h2 id="s2">${esc(sectionTitle('s2'))}</h2>`)
  if (model.productRows === null) {
    push('<p>没有关联到 ASIN 记录，本节跳过。</p>')
  } else {
    push(htmlTable(['项目', '值'], model.productRows.map(([label, value]) => [esc(label), esc(value)])))
    if (model.marketplace.units) {
      push(`<p>计量习惯：长度用 <strong>${esc(model.marketplace.units.length)}</strong>、重量用 <strong>${esc(model.marketplace.units.weight)}</strong>、温度用 <strong>${esc(model.marketplace.units.temperature)}</strong>。</p>`)
    }
    if ((model.marketplace.habits ?? []).length > 0) {
      push('<p>该站点的购买习惯（每条都标了依据）：</p><ul>')
      for (const habit of model.marketplace.habits) push(`<li>${esc(habit.text)}<br><span class="pill">依据：${esc(habit.source)}</span></li>`)
      push('</ul>')
    }
  }

  /* 三 */
  push(`<h2 id="s3">${esc(sectionTitle('s3'))}</h2>`)
  if (!model.plan) {
    push('<p>本轮没有生成全局计划。</p>')
  } else {
    push(`<h3>3.1 埋词位置（${model.plan.positions.length} 个，按权重降序）</h3>`)
    push(htmlTable(['#', '位置', '落点', '权重', '本轮写入'], model.plan.positions.map((position, index) => [
      String(index + 1), esc(position.label), esc(position.where), esc(position.weightLabel),
      (model.plan.writtenPositions ?? []).includes(position.id) ? '<span class="ok">✅</span>' : '—',
    ])))
    push('<blockquote>Item Highlights 不在 SOP §三 的 11 个位置里 —— 该 SOP 早于这个字段。它 2026-07 才进注册表，是 Alexa for Shopping 的检索入口。</blockquote>')

    const matrix = model.plan.coverageMatrix
    push('<h3>3.2 埋词覆盖矩阵（计划 vs 实际）</h3>')
    push(`<p>每个词计划落 <strong>${matrix.summary.averagePlanned}</strong> 处，实际落 <strong>${matrix.summary.averagePlaces}</strong> 处。差值就是还能加深的空间。</p>`)
    const headers = ['关键词', '层级', '主人', ...matrix.positions.map(position => position.label), '实际', '计划', '差']
    const rows = matrix.rows.map(row => [
      esc(row.keyword), esc(row.tier ?? '未测'), esc(labelForField(row.owner)),
      ...matrix.positions.map(position => (row.cells[position.id] ? '<span class="ok">✅</span>' : '<span style="color:#d0d7de">·</span>')),
      String(row.total), String(row.plannedCount), row.gap > 0 ? `<strong class="bad">${row.gap}</strong>` : '0',
    ])
    push(htmlTable(headers, rows))

    push('<h3>3.3 关键词分配（每个词一个主人 + 复用理由）</h3>')
    push(htmlTable(['关键词', '主人', '为什么放这里', '支持位置'], model.plan.allocation.entries.map(entry => [
      esc(entry.keyword), esc(entry.ownerLabel), esc(entry.ownerReason),
      entry.supporting.length === 0 ? '—' : entry.supporting.map(item => `<strong>${esc(item.positionLabel)}</strong>：${esc(item.reason)}`).join('<br>'),
    ])))
    /* Same title-rule disclosure as the Markdown rendering — a site that declines
       the word-repeat rule must say so, not show a title that silently skipped it. */
    const capacity = model.plan.allocation?.titleCapacity
    if (capacity) {
      if (capacity.applicable === false) {
        push(`<p><strong>标题</strong>：${esc(capacity.note ?? '本站点不做单词重复约束')}</p>`)
      } else {
        const spilled = capacity.rejected.length > 0
          ? `，让出 ${capacity.rejected.length} 个给五点（${esc(capacity.rejected.join('、'))}）`
          : ''
        push(`<p><strong>标题的单词重复约束</strong>：同一个词最多出现 <strong>${capacity.limit}</strong> 次。本轮保留 ${capacity.kept.length} 个词进标题${spilled}。</p>`)
      }
    }
    if (model.plan.allocation.violations.length > 0) {
      push('<h4>分配冲突</h4><ul>')
      for (const violation of model.plan.allocation.violations) push(`<li class="bad">${esc(violation.detail)}</li>`)
      push('</ul>')
    }
  }

  /* 四 */
  push(`<h2 id="s4">${esc(sectionTitle('s4'))}</h2>`)
  if (model.rows.length === 0) push('<p>本轮没有字段草稿。</p>')
  /* 与 Markdown 同一句话、同一个判据：没有发布登记 ≠ 发布值是空的。 */
  if (model.rows.length > 0 && model.activation.count === 0) {
    push('<div class="warn-box"><strong>本轮没有发布登记</strong>，所以逐字段不印「实际发布值」——'
      + '这不是「发布值是空的」，是还没有人登记过发布（§6）。登记之后重出报告，这一节会逐个字段印出线上实际的值。</div>')
  }
  /* 与 Markdown 同一张表、同样的五列（R-89）。渲染器不同，判据与数据源是同一个。 */
  if (model.rows.length > 0) {
    push('<h3>4.1 对照表（一屏看完这一轮改了什么）</h3>')
    push('<table class="tbl"><thead><tr><th>序号</th><th>属性字段</th><th>优化前值</th>'
      + '<th>优化后值</th><th>优化后详细说明</th></tr></thead><tbody>')
    model.rows.forEach((row, index) => {
      push(`<tr><td>${index + 1}</td><td>${esc(row.label)}<br><code>${esc(row.field)}</code></td>`
        + `<td>${esc(cellText(row.before))}</td><td>${esc(cellText(row.after))}</td>`
        + `<td>${esc(cellText(row.rationale))}</td></tr>`)
    })
    /* R-91：模板要求但本轮没草稿的字段 —— 一样占一行，写「本轮没有草稿」。 */
    ;(model.templateMissing ?? []).forEach((item, index) => {
      push(`<tr><td>${model.rows.length + index + 1}</td><td>${esc(item.label)}<br><code>${esc(item.id)}</code></td>`
        + `<td>—</td><td><strong>（本轮没有草稿）</strong></td><td>模板要求这一格`
        + `${item.required ? '，且它是<strong>必填</strong>' : ''}${item.limit === null ? '' : `（上限 ${esc(item.limit)}）`}`
        + ' —— 本轮没有生成草稿</td></tr>')
    })
    push('</tbody></table>')
    if ((model.templateMissing ?? []).length > 0) {
      const requiredMissing = model.templateMissing.filter(item => item.required).length
      push(`<p class="meta">这一轮覆盖 ${model.rows.length} / ${model.rows.length + model.templateMissing.length} 个模板字段，`
        + `缺 ${model.templateMissing.length} 个（其中必填 ${requiredMissing} 个）。缺的不是「不用管」—— `
        + '印出来就是为了让「还差多少」有一个数字。</p>')
    }
  }
  for (const group of model.groups) {
    push(`<h3>${esc(group.label)}</h3>`)
    for (const row of group.rows) {
      /* 字段锚点：`#field-<field>`。第八节的违规行、附录的证据类都往这里跳 ——
         这是「证据跳转」的另一半（从结论回到它说的那一格）。 */
      push(`<h4 id="field-${esc(row.field)}">${esc(row.label)}${row.accepted ? ' <span class="ok">✅</span>' : ''}</h4>`)
      if (row.before !== null) push(`<p class="meta">${beforeLabelHtml(model.beforeSource)}</p><pre>${esc(row.before)}</pre>`)
      if (row.after !== null) {
        push(`<p class="meta">优化后${row.publishable ? '（可直接复制粘贴到亚马逊后台）' : '（该字段不能通过表格上传，要人工在对应编辑器里填）'}</p>`)
        push(`<pre>${esc(row.after)}</pre>`)
      }
      /* 实际发布值（§28.2）。只在真的登记过这个字段时印。 */
      if (row.published !== null) {
        push(`<p class="meta">实际发布值（登记 <code>${esc(row.published.publicationId)}</code>，${esc(row.published.publishedAt)}，草案版本 ${row.published.draftVersion === null ? '未记' : `v${esc(String(row.published.draftVersion))}`}）</p>`)
        push(`<pre>${esc(String(row.published.value ?? '（发布的是空值）'))}</pre>`)
        if (row.published.agrees === true) push('<p class="good">与本轮草案<strong>一致</strong>。</p>')
        else if (row.published.agrees === false) push('<p class="bad">⚠️ 与本轮草案<strong>不同</strong> —— 线上不是这份草案的文本。</p>')
        else push('<p class="meta">本轮草案里<strong>没有这个字段</strong>（登记里多出来的），所以「一致不一致」问不出来。</p>')
      }
      /* 字段级置信度/风险（§28.2）：等级 + 全部理由。 */
      push(`<p class="assess"><strong>置信度 ${esc(row.confidence.label)}</strong>：${esc(row.confidence.reasons.join('；'))}　｜　`
        + `<strong>风险 ${esc(row.risk.label)}</strong>：${esc(row.risk.reasons.join('；'))}</p>`)
      if (row.rationale !== null) push(`<blockquote><strong>为什么这样改：</strong>${esc(row.rationale)}</blockquote>`)
      if (row.expected !== undefined && row.expected !== null) {
        push(`<blockquote><strong>预期：</strong>${esc(expectationLine(row.expected))}</blockquote>`)
        if (row.expected.watchFor !== null && row.expected.watchFor !== undefined) {
          push(`<blockquote><strong>反向指标：</strong>${esc(row.expected.watchFor)}</blockquote>`)
        }
        push(`<blockquote class="basis"><strong>依据：</strong>${esc(row.expected.basis)}</blockquote>`)
      }
      if (row.keywords.length > 0) {
        const names = row.keywords.map(entry => (typeof entry === 'string' ? entry : entry.keyword)).join('、')
        push(`<blockquote><strong>植入了：</strong>${esc(names)}</blockquote>`)
      }
      if (row.needsConfirmation) push('<blockquote>⚠️ 这一项是<strong>事实</strong>不是文案。模型只能提议，必须由人对着实物确认后再填。</blockquote>')
      if (row.violations.length > 0) {
        push('<ul>')
        for (const violation of row.violations) {
          push(`<li><span class="no">${esc(SEVERITY_LABEL[violation.severity] ?? violation.severity)}</span> ${esc(violation.title)}（${esc(violation.ruleId)}，依据 ${esc(violation.source)}）：${esc(violation.messages.join('；'))}</li>`)
        }
        push('</ul>')
      }
      /* 证据跳转（§28.4）：这个字段依据哪几类冻结证据 —— 链接到附录里的 `#ev-<kind>`。 */
      const fieldEvidence = evidenceForField(model, row.field)
      if (fieldEvidence.length > 0) {
        push(`<p class="meta">依据的证据这一类：${fieldEvidence.map(entry => `<a href="#ev-${esc(entry.kind)}">${esc(entry.label)}</a>`).join('、')}</p>`)
      }
    }
  }

  /* 五 */
  push(`<h2 id="s5">${esc(sectionTitle('s5'))}</h2>`)
  push(`<p>已填 <strong>${model.attributes.filledCount}/${model.attributes.target}</strong>。属性权重 2026 起已超过后台搜索词，每个空字段是 COSMO 知识图谱的一个断连。</p>`)
  push(htmlTable(['属性', '当前值', '需要具体化'], model.attributeRows.map(row => [
    esc(row.label),
    row.value === null ? '<span class="no">❌ 空</span>' : esc(row.value),
    row.specific ? '是' : '',
  ])))
  if (model.attributes.empty.length > 0) {
    push(`<p><strong>还空着的 ${model.attributes.empty.length} 项：</strong>${esc(model.attributes.empty.map(id => ATTRIBUTES[id]?.label ?? id).join('、'))}</p>`)
  }

  /* 六 */
  const pasteable = model.pasteable
  if (pasteable.length > 0) {
    push(`<h2 id="s6">${esc(sectionTitle('s6'))}</h2><p>以下文本块可以逐段复制进卖家后台，不需要再改。</p>`)
    for (const row of pasteable) push(`<h4>【${esc(row.label)}】</h4><pre>${esc(row.after)}</pre>`)
  }

  /* 七 */
  const surfaceRows = model.surfaceRows
  if (surfaceRows.length > 0) {
    push(`<h2 id="s7">${esc(sectionTitle('s7'))}</h2><p>这些字段不在上架表格里，各有自己的编辑入口。文案是草案，需要人工搬过去。</p>`)
    for (const row of surfaceRows) {
      push(`<h4>【${esc(row.label)}】${row.accepted ? '' : '（未采纳）'}</h4><pre>${esc(row.after)}</pre>`)
      if (row.rationale !== null) push(`<blockquote>${esc(row.rationale)}</blockquote>`)
    }
  }

  /* 八 */
  push(`<h2 id="s8">${esc(sectionTitle('s8'))}</h2>`)
  if (!model.validation) {
    push('<p>本轮没有留下校验结果。</p>')
  } else if (model.validation.violations.length === 0) {
    const skippedCount = (model.validation.skipped ?? []).length
    push(skippedCount === 0
      ? '<p class="good">机检规则全部通过。</p>'
      : `<p>机检规则没有发现违规，但其中 <strong>${skippedCount}</strong> 条在本站点不适用、<strong>没有执行</strong> —— 见 8.2，不要把「不适用」读成「通过」。</p>`)
  } else {
    push(htmlTable(['严重度', '规则', '字段', '说明', '依据'], model.validation.violations.map(violation => [
      `<span class="${violation.severity === 'block' ? 'no' : ''}">${esc(SEVERITY_LABEL[violation.severity] ?? violation.severity)}</span>`,
      esc(violation.ruleId), fieldAnchorLink(model, violation.field, labelForField(violation.field)), esc(violation.messages.join('；')), esc(violation.source),
    ])))
  }

  if (model.gates) {
    push('<h3>8.1 六道闸门</h3>')
    push(htmlTable(['闸门', '结果', '说明'], model.gates.gates.map(gate => [
      esc(gate.label), gate.pass ? '<span class="ok">✅ 通过</span>' : '<span class="no">❌ 未过</span>', esc(gate.detail),
    ])))
    push('<blockquote>闸门与规则是两件事：规则判「合不合法」，闸门判「全不全」。一份完全合法的文案可以只写了 11 个章节里的 4 个。</blockquote>')
  }

  /* 8.2 — rules that could not be judged here, stated rather than silently passed. */
  const skipped = model.validation?.skipped ?? []
  if (skipped.length > 0) {
    push('<h3>8.2 本站点不适用的规则（<strong>不是通过</strong>）</h3>')
    push('<p>下面这些规则在本站点无法判定，因此<strong>没有执行</strong>。它们既不是通过，也不是违规 —— 把「不适用」读成「通过」正是本报告要避免的事。</p>')
    push(htmlTable(['规则', '字段', '严重度', '原因', '依据'], skipped.map(entry => [
      esc(entry.ruleId), fieldAnchorLink(model, entry.field, labelForField(entry.field)),
      esc(SEVERITY_LABEL[entry.severity] ?? entry.severity), esc(entry.reason), esc(entry.source),
    ])))
  }

  push('<h3>8.3 这份报告不判定的事（Agent 审阅清单）</h3>')
  push('<p>下面这些是规则文档要求、但只能由模型或人来判断的。机检通过<strong>不代表</strong>这些也通过。工作台的「校验体系 → Agent 审阅」面板逐项记结论（可以逐字段），每条结论必须引用证据。</p>')
  push(htmlTable(['检查项', '依据', '要问的问题', '只能人判'], model.llmOnly.map(check => [
    `${esc(check.label ?? check.id)}（${esc(check.id)}）`, esc(check.source), esc(check.ask),
    check.needsHuman === true ? '是' : '',
  ])))

  /* 九 */
  push(`<h2 id="s9">${esc(sectionTitle('s9'))}</h2>`)
  if (model.budgets.length === 0) {
    push('<p>没有可测量的字段。</p>')
  } else {
    push(htmlTable(['字段', '用量', '上限', '单位', '来源'], model.budgets.map(row => [
      esc(row.label), String(row.used), `${row.max}${row.over ? ' <span class="no">❌</span>' : ''}`,
      row.unit === 'bytes' ? '字节' : '字符',
      row.limitSource === 'documented' ? '文档规定' : '经验值',
    ])))
    push('<blockquote>后台搜索词按<strong>字节</strong>算，其他按<strong>字符</strong>算。一个中文字 3 字节，所以 249 字节装不下 249 个中文字 —— 超了亚马逊可能整个字段都不索引。</blockquote>')
    push('<blockquote>「经验值」是我们给的区间，不是文档规定的上限。</blockquote>')
  }

  /* 十 */
  if (model.hasFactLedger === true) {
    const ledger = model.plan.factLedger
    push(`<h2 id="s10">${esc(sectionTitle('s10'))}</h2>`)
    push(`<p>记录了 <strong>${ledger.summary.total}</strong> 个事实，每个事实只允许一个取值。</p>`)
    if (ledger.conflicts.length > 0) {
      push('<h3>⚠️ 事实冲突</h3><ul>')
      for (const conflict of ledger.conflicts) push(`<li><strong>${esc(conflict.label)}</strong>：${esc(conflict.values.join(' / '))} —— ${esc(conflict.detail)}</li>`)
      push('</ul>')
    } else {
      push('<p class="good">没有冲突：同一个事实在各字段里的取值一致。</p>')
    }
    const withOccurrences = ledger.rows.filter(row => row.occurrences.length > 0)
    if (withOccurrences.length > 0) {
      push(htmlTable(['事实', '取值', '出现位置'], withOccurrences.map(row => [
        esc(row.label), esc(row.value), esc(row.occurrences.map(occurrence => labelForField(occurrence.field)).join('、')),
      ])))
    }
  }

  /* 十一 */
  push(`<h2 id="s11">${esc(sectionTitle('s11'))}</h2>`)
  push('<p>这些采集不到、也推断不出来。填错变体关系或类目会影响整组链接，所以单独列出来。</p>')
  push(htmlTable(['字段', '说明', '库内状态'], model.manualFields.map(field => [esc(field.label), esc(field.why), esc(manualStatusLabel(field))])))

  /* 十二 —— 与 Markdown 同一份 `model.delivery`，同一个判据，两种渲染。 */
  push(`<h2 id="s12">${esc(sectionTitle('s12'))}</h2>`)
  if (model.delivery === null || model.delivery === undefined || model.delivery.ok !== true) {
    push('<p><em>交付边界读不出来（这一份报告没有挂在轮次上）—— 这不是「没有要交付的东西」。</em></p>')
  } else {
    const delivery = model.delivery
    push(`<p>这一轮 <strong>${delivery.counts.operations}</strong> 条操作：`
      + `可复制粘贴 ${delivery.counts.ready} · 去独立编辑器 ${delivery.counts.editor} · `
      + `草案未采纳（不要去改）${delivery.counts.notAccepted} · 本轮没有生成 ${delivery.counts.noText} · `
      + `必须人工填 ${delivery.counts.humanRequired} · 已登记发布 ${delivery.counts.registered}</p>`)
    push('<p>每一条都是「去哪儿、做什么」。<strong>勾选状态不落库</strong> —— 报告是一份静态文档，'
      + '而「人做过什么」的持久事实在模块 14 的发布登记里（见 12.2）。'
      + '已经登记过发布的那些字段，下面是勾上的。</p>')
    push('<ul style="list-style:none;padding-left:0">')
    for (const operation of delivery.operations) {
      push(`<li><input type="checkbox" disabled${operation.status === 'registered' ? ' checked' : ''}> `
        + `<strong>${esc(operation.fieldLabel)}</strong>（${esc(operation.surfaceLabel)}）— ${esc(operation.action)} `
        + `<span class="pill">${esc(operation.statusLabel)}</span></li>`)
    }
    push('</ul>')

    push('<h3>12.1 交付边界：哪些字段是这个插件给的，哪些要人填</h3>')
    push(htmlTable(['类别', '条数', '这一轮的具体字段'], [
      ['插件提供（这一轮有草案）', String(delivery.boundary.plugin.count), esc(delivery.boundary.plugin.note)],
      ['插件<strong>不提供</strong>', String(delivery.boundary.humanOnly.count),
        esc(delivery.boundary.humanOnly.fields.map(id => labelForField(id)).join('、'))],
      ['插件会提供、<strong>这一轮没有生成</strong>', String(delivery.boundary.notGenerated.count),
        esc(delivery.boundary.notGenerated.fields.map(field => labelForField(field)).join('、'))],
    ]))
    push('<blockquote>第二行与第三行<strong>不是一件事</strong>：第二行是「本仓没有这些字段的来源」'
      + '（SKU / 库存 / 价格 / 类目 / 变体 / 浏览节点 / 目标人群，采集不到也推断不出来，只能人填）；'
      + '第三行是「插件本来会产出这些字段的草案，但这一轮没有生成它」。把这两句压成一句，'
      + '读者就会去后台找一个插件根本不提供的字段的值。</blockquote>')
    if (delivery.unmappedSurfaces.length > 0) {
      push(`<p><strong>⚠️ 有 ${delivery.unmappedSurfaces.length} 个 section 没有登记交付落点（${esc(delivery.unmappedSurfaces.join('、'))}）</strong>`
        + ' —— 它们不会被归进任何一个落点里，这是注册表变了而落点表没跟上。</p>')
    }

    push('<h3>12.2 发布登记：接受草案 ≠ 已发布</h3>')
    push('<div class="warn-box"><strong>接受草案 ≠ 已发布。</strong>'
      + '<p>这份报告里的文字，在你到卖家后台改完、并登记发布之前，线上<strong>一个字都没变</strong>。'
      + '这个插件不会在 Seller Central 点任何按钮，也不调任何发布接口 —— 它只记录你做了什么。</p></div>')
    const registration = delivery.registration
    push('<ul>')
    push('<li>登记入口：工作台「优化 → 发布记录」的表单（页面会预填运行 id 与草案版本）</li>')
    push(`<li>运行 id：<code>${esc(registration.runId)}</code></li>`)
    push(`<li>草案版本：${registration.draftVersionKnown ? `<code>v${esc(String(registration.draftVersion))}</code>` : '<em>读不到（这不是「版本是 0」）</em>'}</li>`)
    push(`<li>已登记的字段：${registration.registered.count} 个`
      + (registration.registered.count === 0
        ? '（<strong>一条发布都还没有登记过</strong> —— 这不是「登记里没有字段」）'
        : `（最近一条 <code>${esc(registration.registered.latestId)}</code>，${esc(registration.registered.latestAt)}）`) + '</li>')
    push('</ul>')
    push('<blockquote>下面这几句是<strong>经验</strong>，不是由这一轮的内容推出来的：改动前先截图存档（万一要回滚）；'
      + '每改完一个字段保存一次；改完 24 小时看是否触发审核、48 小时看排名与广告数据；'
      + '有广告活动的 ASIN 改完要检查广告组的关键词质量分。</blockquote>')

    /* 12.3 实际发布值（§28.2 第三件）。与 Markdown 同一份 `model.activation`。 */
    if (model.activation.count > 0) {
      const activation = model.activation
      push('<h3 id="s12-3">12.3 实际发布值（从发布登记读回来）</h3>')
      push('<ul>')
      push(`<li>登记 <strong>${activation.count}</strong> 条`
        + (activation.latest === null ? '' : `，最近一条 <code>${esc(activation.latest.id)}</code>（${esc(activation.latest.publishedAt ?? '')}，草案版本 ${activation.latest.draftVersion === null ? '未记' : `v${esc(String(activation.latest.draftVersion))}`}）`) + '</li>')
      if (activation.deviation !== null) {
        const deviation = activation.deviation
        push(`<li>§6 的偏离判定（<strong>登记时冻结</strong>，不随今天的草案重算）：`
          + `${activation.deviated ? `<strong class="bad">偏离</strong>（${activation.deviationRule === 'core-field' ? '改了核心字段' : '改动超过阈值'}）` : '<span class="good">未偏离</span>'}`
          + `，改动 <strong>${deviation.changedCount}/${deviation.total}</strong> 个字段（${Math.round((deviation.ratio ?? 0) * 100)}%）`
          + `${(deviation.coreChanged ?? []).length === 0 ? '' : `，核心字段：${esc(deviation.coreChanged.map(field => labelForField(field)).join('、'))}`}</li>`)
      } else {
        push('<li>§6 的偏离判定：这条登记<strong>没有冻结的差异结果</strong>（不是「没有偏离」）</li>')
      }
      if (activation.uncovered.length > 0) {
        push(`<li>发布里出现、批准草案<strong>没有覆盖</strong>的字段（记录但不计入偏离比值）：${esc(activation.uncovered.join('、'))}</li>`)
      }
      push('</ul>')
      push(htmlTable(['字段', '本轮草案', '实际发布', '一致', '登记'], activation.entries.map(entry => [
        esc(labelForField(entry.field)), esc(brief(entry.draftAfter)), esc(brief(entry.value)),
        entry.agrees === true ? '<span class="ok">✅ 一致</span>' : (entry.agrees === false ? '<span class="bad">⚠️ 不同</span>' : '本轮未覆盖'),
        `${esc(entry.publicationId ?? '—')} @ ${esc(entry.publishedAt ?? '—')}`,
      ])))
    }
  }

  /* 附录、证据包（§28.4 的证据跳转落点）。每一类带 `id="ev-<kind>"` —— 第四节里每个
     字段的「依据的证据这一类」链接指向这里。 */
  if (model.evidencePack !== null) {
    const pack = model.evidencePack
    push(`<h2 id="s-evidence">${esc(sectionTitle('s-evidence'))}</h2>`)
    push(`<p>冻结于 ${pack.frozenAt === null ? '读不到' : esc(pack.frozenAt)}${pack.lateFreeze ? '（<strong>补冻</strong>：晚于这一轮收尾）' : ''}。`
      + (pack.counts === null ? '' : `十一类里：冻结 ${pack.counts.frozen} · 不存在 ${pack.counts.absent} · 未建模 ${pack.counts.notModelled}`
        + (pack.missing.length > 0 ? `；包里缺 ${pack.missing.length} 类（${esc(pack.missing.join('、'))}）` : '；十一类齐全') + '。') + '</p>')
    push('<table><thead><tr><th>类</th><th>状态</th><th>观测时间</th><th>来源</th><th>条数</th></tr></thead><tbody>')
    for (const row of pack.rows) {
      push(`<tr id="ev-${esc(row.kind)}"><td>${esc(row.label)}</td><td>${esc(evidenceStatusLabel(row.status))}</td>`
        + `<td>${row.at === null ? '<em>无日期</em>' : esc(row.at)}</td><td>${esc(row.source ?? '—')}</td>`
        + `<td>${row.count === null ? '不适用' : row.count}</td></tr>`)
    }
    push('</tbody></table>')
    push('<blockquote>「不存在」（absent）与「0 条」不是一件事：前者是这个对象上没有可冻结的东西，'
      + '后者是读过了、答案是 0。「未建模」是本仓没有这一类的来源 —— 三种说法都不许互相代替。</blockquote>')
  }

  /* 十三 */
  push(`<h2 id="s13">${esc(sectionTitle('s13'))}</h2>`)
  push(htmlTable(['检查项', '标准', '结果', '状态'], selfCheck(model).map(check => [
    esc(check.item), esc(check.standard), esc(check.result),
    checkState(check) === 'unverified'
      ? '<span class="pill">—</span>'
      : (checkState(check) === 'ok' ? '<span class="ok">✅</span>' : '<span class="no">❌</span>'),
  ])))
  push('<blockquote>状态「—」= <strong>这一项没有执行</strong>（不是通过，也不是不达标）—— 与校验闸门的 <code>unverified</code> 是同一件事。</blockquote>')

  push(`<hr><p class="meta">生成时间：${esc(new Date().toISOString())}｜规则集 ${esc(model.rules?.version ?? '—')}｜埋词位置 ${planPositionText(model)}｜字段词汇 ${Object.keys(FIELDS).length} 项 + ${REQUIRED_ATTRIBUTE_TARGET} 项属性</p>`)
  push('</div></body></html>')

  return parts.join('\n')
}

export { REQUIRED_ATTRIBUTE_IDS, parseJson }

/* ── Excel ─────────────────────────────────────────────────────────────────── */

/**
 * The Excel rendering — the **third** rendering of the same model.
 *
 * ## Why a spreadsheet at all
 *
 * The audit's F14-10 gap was literal: this repo could read xlsx and could not
 * write it, so the only machine-readable export was a CSV of the ASIN table. An
 * optimization report is a document people argue with: whoever receives it wants
 * the per-field rows in a grid they can sort, filter against their own sheet, and
 * hand to someone else. A spreadsheet is that, and a PDF-shaped HTML is not.
 *
 * ## Same model, same numbers — structurally
 *
 * Every cell comes from a field of `model`. Nothing here re-reads the store, and
 * nothing recomputes a number that the model already carries: the counts, the
 * per-field rows, the header, the freshness verdict are the *same objects* the
 * other two renderings read. Mutation test: corrupt `model.provenance` or
 * `model.exportHeader` and all three renderings go red together
 * (`tests/f14-10-report-export.mjs`).
 *
 * ## What a sheet is, here
 *
 * One sheet per report section a reader would want on its own — 报告头 (with the
 * freshness block), 报告出处, 数据新鲜度, 结论, 逐字段, 属性字段, 人工字段, 自检总表,
 * 证据包. The point of splitting is that 「逐字段」 is the sheet people actually
 * sort, and burying it under six paragraphs of header is how the export stops
 * being used.
 *
 * ## No live clock in here
 *
 * `renderHtml`'s footer prints `new Date()`; this renderer does not, on purpose:
 * the file says **when the data is from** (`freshness.generatedAt`, read from the
 * run), which is the fact a reader needs, and it makes the same model render to
 * the same bytes — so a test can assert the stored artifact equals a fresh
 * rendering instead of "some bytes".
 */
export function renderExcel(model) {
  const headerRows = [
    ['字段', '值', '这一格是怎么来的'],
    ...model.exportHeader.rows.map(row => [row.label, String(row.value ?? ''), String(row.note ?? '')]),
    [],
    ['数据新鲜度结论', model.freshness.statement, `这一行不是一句话贴上去的：生成时刻、数据截止、两者差值、证据逐类状态都在「数据新鲜度」这一张表里，改任一项这句话就变。`],
  ]

  const provenanceRows = [
    ['字段', '值', '这一格是怎么来的'],
    ...model.provenance.rows.map(row => [row.label, String(row.value ?? ''), String(row.note ?? '')]),
  ]

  const freshness = model.freshness
  const freshnessRows = [
    ['项', '值', '说明'],
    ['非实时', `${freshness.label} —— 这一份文件不是实时数据`,
      '文件是那一刻的字节；之后的采集、改价、改文案都不会出现在这里。'],
    ['生成时刻', freshness.generatedAt ?? '读不到（这一轮没有记录收尾/开始时间）',
      'optimization_run.finished_at，落库时写入的收尾时刻；没有就退到 started_at，两者都没有就是「没有记录」。'],
    ['数据截止', freshness.cutoff.text,
      `证据包里最新的一条观测时间（${freshness.cutoff.label ?? '—'}）；${freshness.cutoff.kinds} 类里 ${freshness.cutoff.dated} 类带日期。`],
    ['两者相差', freshness.lag === null ? '读不到（缺生成时刻或缺数据截止，**不是 0**）' : freshness.lag.text,
      '生成时刻减数据截止。负数表示数据截止晚于生成时刻 —— 那是一个要看的异常，不是一个可以抹平成 0 的数。'],
    ['证据类数', `${freshness.counts.evidenceFrozen} 冻结 / ${freshness.counts.evidenceAbsent} 不存在 / ${freshness.counts.evidenceNotModelled} 未建模`,
      '十一类证据在这一次冻结时各自的状态。「不存在」不是「0 条」，「未建模」是「本仓没有这一类的来源」。'],
    ['指标口径限制', `${freshness.counts.metricsNoSource} 条本仓没有来源 · ${freshness.counts.metricsPartial} 条只有一部分口径 · ${freshness.counts.metricsCurrentOnly} 条只有当前值`,
      '九类观测指标在 domain/observe/metrics.js 里的登记；逐条在下面两张表。'],
    ['四态条目', `共 ${freshness.counts.absenceEntries} 条（本仓没有该来源 ${freshness.counts.absenceNoSource} · 本仓没有为它建模 ${freshness.counts.absenceNotModelled} · 有来源但还没有记录 ${freshness.counts.absenceNotRecorded}）`,
      '「没有」的四种说法在 domain/reports/gaps.js 里各只有一句拼写；「读到了，答案是 0」是发现不是缺口，所以不计入这四条。'],
    [],
    ['证据类', '状态', '观测时间', '来源', '条数', '四态结论'],
    ...freshness.evidence.rows.map(row => [
      row.label, row.statusLabel, row.at ?? '无日期', row.source ?? '—',
      row.count === null ? '不适用' : row.count,
      row.absence === null ? '—（这一类有内容，没有缺口要说）' : row.absence.conclusion,
    ]),
    [],
    ['指标', '可用性', '历史', '来源表', '四态结论'],
    ...freshness.metrics.rows.map(row => [
      row.label, row.availabilityLabel, row.historyLabel, row.table ?? '本仓没有这张表',
      row.absences.length === 0 ? '—（可用性与历史都够用）' : row.absences.map(entry => entry.conclusion).join('；'),
    ]),
    [],
    ['四态', '条目', '结论', '该做什么', '为什么'],
    ...freshness.absences.map(entry => [
      entry.kind, entry.label, entry.conclusion, entry.action, entry.reason,
    ]),
  ]

  /* 完成率读一次，用一次（这个模型上它不会变，读两遍只是给「两处各算一遍」留口子）。 */
  const excelFillRate = planFillRate(model)
  const conclusions = [
    ['项', '值', '出处'],
    ['采纳字段', model.accepted.length, '草案行 accepted = 1'],
    ['拒绝字段', model.rejected.length, '草案行 accepted = 0'],
    ['待定字段', model.pending.length, '草案行 accepted 为 NULL'],
    ['阻断违规', model.counts.block, '本轮校验计数（与第八章同一份）'],
    ['警告', model.counts.warn, '本轮校验计数（与第八章同一份）'],
    ['属性填写', `${model.attributes.filledCount}/${model.attributes.target}`, 'attributeCoverage(afterFields)'],
    ['埋词完成率', model.plan?.coverageMatrix
      ? (excelFillRate === null
        ? '读不到（这一轮的快照里没有 fillRate —— 不是 0%）'
        : Math.round(excelFillRate * 100) / 100)
      : '这一轮没有全局计划',
    'plan.coverageMatrix.summary.fillRate（0–1 的小数）'],
    ['闸门', model.gates === null || model.gates === undefined ? '这一轮没有跑闸门' : `${model.gates.passed}/${model.gates.total}`, 'gates.passed / gates.total'],
    ['可写回字段', model.writeback.writable.count, `writebackSplit：${model.writeback.writable.groups}`],
    ['只出草案字段', model.writeback.draftOnly.count, `writebackSplit：${model.writeback.draftOnly.groups}`],
    ['本轮写回', model.applyListing === null
      ? '未尝试（applyListing 关闭）'
      : (model.applyListing.ok === true ? `成功，${model.applyListing.applied} 个字段` : `失败：${model.applyListing.error ?? '未知错误'}`),
    'applyListing，只在真的尝试过时才有值'],
  ]

  /* 2026-10-26（R-89）：加「序号」与「优化后详细说明」两列 —— 与 Markdown / HTML 那张
     五列表是同一份内容（序号 / 属性字段 / 优化前值 / 优化后值 / 优化后详细说明），
     表格里的其余列是这个 sheet 本来就有的判断列。 */
  const fieldRows = [
    ['序号', '字段', '名称', '章节', '优化前', '优化后', '优化后详细说明', '采纳', '阻断', '警告', '可信度', '风险', '实际发布值', '与草案'],
    ...model.rows.map((row, index) => [
      index + 1,
      row.field, row.label, row.section,
      row.before === null ? '（无原值）' : String(row.before),
      row.after === null ? '（无草案）' : String(row.after),
      row.rationale === null || String(row.rationale).trim() === '' ? '（没写说明）' : String(row.rationale),
      row.accepted ? '是' : '否',
      row.block, row.warn,
      row.confidence?.label ?? '—',
      row.risk?.label ?? '—',
      row.published === null || row.published === undefined ? '没有登记' : String(row.published.value ?? ''),
      row.published === null || row.published === undefined
        ? '—'
        : (row.published.agrees === true ? '一致' : (row.published.agrees === false ? '不同' : '本轮未覆盖')),
    ]),
  ]

  const attributeRows = [
    ['属性 id', '名称', '本轮的值', '要对着实物确认'],
    ...model.attributeRows.map(row => [row.id, row.label, row.value === null ? '（未填）' : String(row.value), row.specific === true ? '是' : '否']),
  ]

  const manualRowsSheet = [
    ['字段', '名称', '库内状态', '来源列', '为什么必须人填'],
    ...model.manualFields.map(row => [row.id, row.label, manualStatusLabel(row), row.evidence ?? '库内没有对应列', String(row.note ?? '')]),
  ]

  const selfCheckRows = [
    ['检查项', '标准', '结果', '状态'],
    ...selfCheck(model).map(row => [row.item, row.standard, row.result, checkLabel(row)]),
  ]

  const evidenceRows = model.evidencePack === null
    ? [['类', '状态', '观测时间', '来源', '条数'], ['这一轮没有冻结证据包', '没有包', '—', '—', '不适用']]
    : [
      ['类', '状态', '观测时间', '来源', '条数'],
      ...model.evidencePack.rows.map(row => [
        row.label, evidenceStatusLabel(row.status), row.at === null ? '无日期' : row.at,
        row.source ?? '—', row.count === null ? '不适用' : row.count,
      ]),
    ]

  return writeXlsx([
    { name: '报告头', rows: headerRows, widths: [18, 60, 90] },
    { name: '报告出处', rows: provenanceRows, widths: [18, 44, 90] },
    { name: '数据新鲜度', rows: freshnessRows, widths: [18, 34, 80] },
    { name: '结论', rows: conclusions, widths: [18, 40, 60] },
    /* 宽度数组与列数必须同长：加了「序号」与「优化后详细说明」两列，这里跟着加两个宽度。 */
    { name: '逐字段', rows: fieldRows, widths: [5, 18, 14, 12, 50, 50, 50, 6, 6, 6, 8, 8, 40, 10] },
    { name: '属性字段', rows: attributeRows, widths: [22, 16, 40, 8] },
    { name: '人工字段', rows: manualRowsSheet, widths: [18, 16, 28, 20, 60] },
    { name: '自检总表', rows: selfCheckRows, widths: [18, 24, 20, 10] },
    { name: '证据包', rows: evidenceRows, widths: [22, 12, 26, 50, 10] },
  ])
}
